import{_ as s}from"./plugin-vue_export-helper-DlAUqK2U.js";import{c as a,a as n,o as i}from"./app-D4HgcYgq.js";const e={};function l(r,t){return i(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="业务系统设计面试" tabindex="-1"><a class="header-anchor" href="#业务系统设计面试"><span>业务系统设计面试</span></a></h1><h2 id="业务系统" tabindex="-1"><a class="header-anchor" href="#业务系统"><span>业务系统</span></a></h2><h3 id="【困难】如何设计一个秒杀系统-⭐⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【困难】如何设计一个秒杀系统-⭐⭐⭐⭐⭐"><span>【困难】如何设计一个秒杀系统？⭐⭐⭐⭐⭐</span></a></h3><blockquote><p>🎯 目标等级：L3-L4 ｜ ⏱ 建议用时：20 min ｜ 🏷 标签：系统设计 / 秒杀</p></blockquote><h4 id="💎-关键结论" tabindex="-1"><a class="header-anchor" href="#💎-关键结论"><span>💎 关键结论</span></a></h4><p>秒杀应对的是瞬时海量请求，思路是「稳、准、快」：前端静态页 + CDN 挡读流量，答题 + 限流削峰，扣库存用 Redis + Lua 原子操作保证不超卖，只有扣减成功的请求进 MQ 异步建单。最终 DB 写入量等于库存量，而不是请求量。</p><h4 id="⚡-记忆卡片" tabindex="-1"><a class="header-anchor" href="#⚡-记忆卡片"><span>⚡ 记忆卡片</span></a></h4><ul><li><strong>口诀</strong>：静态挡、答题缓、限流削、Lua 扣</li><li><strong>关键词</strong>：瞬时海量请求 ／ 超卖 ／ 分层过滤 ／ Redis+Lua ／ 异步建单</li><li><strong>链路</strong>：前端静态 + CDN → 答题限流 → Redis Lua 扣库存 → MQ 削峰 → 异步建单 → 对账兜底</li></ul><h4 id="📖-核心知识" tabindex="-1"><a class="header-anchor" href="#📖-核心知识"><span>📖 核心知识</span></a></h4><p>秒杀系统所要应对的场景是：<strong>瞬时海量请求</strong>。</p><p><strong>1. 秒杀的难点</strong></p><ul><li><strong>高并发</strong>：可细分为二： <ul><li>并发读：读取剩余库存量以及商品信息；</li><li>并发写：下单后写入订单记录。</li></ul></li><li><strong>超卖</strong>：秒杀商品通常性价比极高甚至赔本赚吆喝，库存 100 件若瞬时下单超过 100 件且处理不当，就会超卖，给商家带来巨大经济损失。</li><li><strong>恶意请求</strong>：有人在多台机器上跑脚本，模拟大量用户抢商品。</li><li><strong>数据库崩溃</strong>：没有 MQ 削峰、没有过载保护，海量请求直接打到数据库，数据库挂掉还会波及其他业务，让整个系统瘫痪。</li><li><strong>对现有业务造成冲击</strong>：秒杀本质是营销活动，不能影响主站。</li></ul><p><strong>2. 设计目标：稳、准、快</strong></p><ul><li><strong>稳（高可用）</strong>：架构要能撑住活动；</li><li><strong>准（一致性）</strong>：减库存方式不能出现超卖；</li><li><strong>快（高性能）</strong>：从前端到后端、依赖组件协同优化。</li></ul><figure><img src="https://raw.githubusercontent.com/dunwu/images/master/archive/2020/07/29c58abfb6e7455fa3711f014fcfb352.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p><strong>3. 前端优化</strong></p><ul><li><strong>静态页面</strong>：秒杀商品页面静态化，减少查库 IO；静态页做 CDN 缓存，前后端分离时还可在反向代理服务器侧设置静态缓存。商品由 ID 标识（如 <code>http://item.xxx.com/item.htm?id=xxxx</code>），对应页面可提前做前端缓存，无需查商品信息。</li><li><strong>按钮控制</strong>：活动开启前下单按钮禁用；点击后禁用一段时间，防止疯狂输出。</li></ul><p><strong>4. 后端优化</strong></p><ul><li><strong>限流、熔断、降级、隔离</strong>：秒杀不应影响现有业务—— <ul><li>隔离：秒杀系统、数据与其他正常业务彼此隔离，互不影响；</li><li>限流：设置阈值，超过阈值拒绝请求，防止数据库被打死；</li><li>降级：保证核心业务继续工作，非核心业务各安天命；</li><li>熔断：不影响别的系统。</li></ul></li><li><strong>多级缓存</strong>：缓存要预热，避免瞬间流量冲击；雪崩、穿透、击穿的常规处理要做好；缓存自身也要高可用。</li><li><strong>流量削峰</strong>：排队、答题、分层过滤—— <ul><li>排队：用消息队列缓冲瞬时流量，但 MQ 自身有上限，积压过多也处理不了；</li><li>答题（摇一摇）：限制秒杀器并延缓请求；</li><li>分层过滤：漏斗式设计，尽可能拦截无效请求。</li></ul></li></ul><figure><img src="https://raw.githubusercontent.com/dunwu/images/master/archive/2020/07/a2edeebfcfca47c0a91d64430927dd65.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><ul><li><strong>减库存</strong>： <ul><li><strong>恶意下单</strong>：结合安全与反作弊——识别频繁下单不付款或重复下单不付款的用户并阻断；限制个人购买数。</li><li><strong>避免超卖</strong>：核心是保证高并发下库存字段不为负数，常见方案： <ol><li>应用程序中通过事务判断，减后库存为负则回滚；</li><li>数据库字段设为无符号整数，减后小于零直接报错；</li><li>使用 CASE WHEN 条件更新：</li></ol></li></ul></li></ul><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">UPDATE</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> item </span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">SET</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> inventory </span><span style="--shiki-light:#383A42;--shiki-dark:#56B6C2;">=</span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;"> CASE</span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;"> WHEN</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> inventory </span><span style="--shiki-light:#383A42;--shiki-dark:#56B6C2;">&gt;=</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> xxx </span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">THEN</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> inventory-xxx </span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">ELSE</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> inventory </span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">END</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li>库存是交易环节的关键数据也是热点数据，但秒杀不需要精确的一致性读，把库存放到缓存（Cache）中可大大提升读性能。</li><li><strong>URL 动态化</strong>：通过 MD5 之类的加密算法加密随机字符串生成 URL，前端获取后经后台校验才能通过，防止提前抢购。</li></ul><h4 id="🔬-扩展知识" tabindex="-1"><a class="header-anchor" href="#🔬-扩展知识"><span>🔬 扩展知识</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li><p>【L3】以 100w QPS 峰值、10w 库存为例，漏斗各层怎么量化？</p><p>漏斗各层的过滤效果是：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>静态页 CDN     // 挡掉 99% 读请求</span></span>
<span class="line"><span>答题/验证码     // 再滤掉 90% 无效请求</span></span>
<span class="line"><span>网关限流        // 削到应用承载量</span></span>
<span class="line"><span>Redis 扣库存    // 仅扣减成功的请求进 MQ 建单</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>最终 DB 写入量 = 库存量（10w），而非请求量（100w）。</p></li><li><p>【L3】库存扣减有哪几种方案，各自的做法与代价是什么？</p><table><thead><tr><th>扣减方案</th><th>关键做法</th><th>代价与适用场景</th></tr></thead><tbody><tr><td>Redis + Lua</td><td><code>if stock &gt;= n then decr</code>，扣成功才发 MQ 建单</td><td>DB 异步落库，需缓存与 DB 对账兜底，是主流方案</td></tr><tr><td>数据库乐观锁 CAS</td><td><code>UPDATE stock SET n = n - ? WHERE id = ? AND n &gt;= ?</code></td><td>简单可靠但热点行锁竞争大，适合库存量小、并发中等的场景</td></tr><tr><td>分段库存</td><td>把 10w 库存拆成 10 个 key 各 1w，随机路由打散热点</td><td>需处理段间余量不均——某段扣完可借调或跳转其他段</td></tr></tbody></table></li><li><p>【L3】秒杀的热点数据为什么要与主站物理隔离？</p><p>秒杀商品用独立 Redis 实例/独立 DB 库表，与主站数据物理隔离，活动结束资源回收。</p><p>Redis 库存与 DB 库存定时对账，不一致以 DB 为准修复。</p></li><li><p>【L4】几种扣减方案怎么权衡，选型看什么？</p><p>Redis + Lua 扣减性能最高（单实例 8~10 万 QPS）但引入缓存与 DB 双存储一致性问题，需对账兜底；纯 DB 乐观锁无一致性问题但热点行锁竞争下 QPS 只有几千；分段库存解决热点但引入段间不均的管理复杂度。</p><p>选型看库存量：库存 100 件没必要上 Redis，库存 10 万 + 峰值十万级才需要。</p></li><li><p>【L4】秒杀系统会在哪些环节失效？</p><p>MQ 建单积压超容量时用户&quot;抢购成功但无订单&quot;，体验崩塌，需积压监控 + 提前告知。</p><p>答题/验证码环节若被脚本破解，漏斗失效，需风控实时升级难度。</p></li><li><p>【L4】未支付订单的库存回补时序怎么设计？</p><p>扣减成功进 MQ 建单，超时未支付的处理路径是：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>扣减成功 → MQ 建单              // 1. 建单链路</span></span>
<span class="line"><span>用户 15 分钟内未支付             // 2. 延时消息触发取消订单</span></span>
<span class="line"><span>回补库存                        // 3. 幂等更新：带订单状态条件</span></span>
<span class="line"><span>扣减/回补记录纳入对账            // 4. 防止&quot;已扣减但既未建单也未回补&quot;的库存黑洞</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>回补动作必须幂等（带订单状态条件更新），且回补记录纳入与扣减记录的对账。</p><p>大促前用全链路压测验证漏斗各层阈值与实际容量匹配，而非凭经验拍数。</p></li></ul><blockquote><p>📚 延伸阅读：<a href="https://time.geekbang.org/column/intro/127" target="_blank" rel="noopener noreferrer">如何设计一个秒杀系统</a>、<a href="https://segmentfault.com/a/1190000020970562" target="_blank" rel="noopener noreferrer">一个秒杀系统的设计思考</a></p></blockquote></details><h4 id="🏭-实战场景" tabindex="-1"><a class="header-anchor" href="#🏭-实战场景"><span>🏭 实战场景</span></a></h4><details class="hint-container details"><summary>详情</summary><p><strong>某平台周年庆秒杀</strong></p><p>场景：100 个 SKU，每个库存 1000 件，预计峰值 50 万 QPS 持续 3 秒，要求不超卖、不影响主站交易。</p><p>漏斗设计：页面静态化 + CDN 挡掉 95% 读流量，答题/验证码滤掉 90% 无效请求，剩余约 2 万 QPS 进应用层。</p><p>库存扣减：单 SKU 库存 1000 件无需分段，Redis Lua 原子扣减即可（总写压力 5 万 QPS 内，单 Redis 实例可扛）。</p><p>扣减成功的 10 万件请求进 MQ 异步建单，DB 写入被平滑到几分钟。</p><p>隔离与兜底：独立部署秒杀集群 + 独立库表与主站隔离；全链路限流兜底，DB 前置 3000 QPS 保护。</p></details><h4 id="⚠️-常见误区" tabindex="-1"><a class="header-anchor" href="#⚠️-常见误区"><span>⚠️ 常见误区</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li>❌ &quot;在网关加个限流，数据库就不会被打挂&quot; → 限流只控制流速，不减少放大效应；不做静态页 + CDN 拦截，读请求照样压到缓存/DB，必须漏斗式分层过滤。</li><li>❌ &quot;应用层先查库存再扣减就能防超卖&quot; → 查与扣不是原子操作，高并发下必然超卖，必须用条件更新 SQL 或 Redis + Lua 原子脚本。</li><li>❌ &quot;秒杀和主站共用部署，加限流就行&quot; → 秒杀流量瞬时放大十万倍，共享资源时拖垮主站交易是大概率事件，应独立部署、隔离故障域。</li></ul></details><h4 id="🔀-发散问题" tabindex="-1"><a class="header-anchor" href="#🔀-发散问题"><span>🔀 发散问题</span></a></h4><ul><li><p><strong>Q：库存扣完后的几十万&quot;已失败&quot;请求怎么低成本地告诉用户？</strong></p><p>→ 库存为 0 后置位 Redis 标志，网关/应用层直接短路返回&quot;已售罄&quot;，不再走后续链路；前端按钮置灰 + 轮询/推送结果，避免用户反复刷。</p></li><li><p><strong>Q：Redis 扣库存成功但建单失败（MQ 丢消息）怎么办？</strong></p><p>→ 扣库存与发 MQ 无法原子，需兜底：建单成功后回写&quot;已建单&quot;标记，定时任务扫描&quot;已扣减但未建单&quot;的记录回补库存或重建订单；同时 Redis 与 DB 对账修正总量。异步建单的状态一致性设计与订单系统相关，见本文档「如何设计一个订单系统？」。</p></li><li><p><strong>Q：秒杀扣库存和优惠券防超发有何异同？</strong></p><p>→ 同为 Redis Lua 原子扣预算 + 异步落库 + 对账兜底，但优惠券还要叠加单用户限领与规则互斥校验，见本文档「如何设计一个营销/优惠券系统？」。</p></li></ul><h3 id="【中等】如何设计一个文件上传系统-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】如何设计一个文件上传系统-⭐⭐⭐"><span>【中等】如何设计一个文件上传系统？⭐⭐⭐</span></a></h3><blockquote><p>🎯 目标等级：L2-L3 ｜ ⏱ 建议用时：15 min ｜ 🏷 标签：系统设计 / 文件存储</p></blockquote><h4 id="💎-关键结论-1" tabindex="-1"><a class="header-anchor" href="#💎-关键结论-1"><span>💎 关键结论</span></a></h4><p>文件上传核心是四件事：存储选型、大文件分片、去重秒传、限流保护。小厂直接用 OSS 云服务，中大厂可基于 FastDFS、MinIO 自建；超大文件切片并行上传并支持断点续传，用文件哈希判重实现秒传，再用令牌桶限流防带宽被刷。</p><h4 id="⚡-记忆卡片-1" tabindex="-1"><a class="header-anchor" href="#⚡-记忆卡片-1"><span>⚡ 记忆卡片</span></a></h4><ul><li><strong>口诀</strong>：大分片、重哈希、断续传、刷限流</li><li><strong>关键词</strong>：OSS/MinIO ／ 分片上传 ／ 断点续传 ／ 哈希秒传 ／ 令牌桶</li><li><strong>链路</strong>：客户端切片 → 哈希判重 → 并行上传 → 服务端合并 → 限流保护</li></ul><h4 id="📖-核心知识-1" tabindex="-1"><a class="header-anchor" href="#📖-核心知识-1"><span>📖 核心知识</span></a></h4><p><strong>1. 存储选型</strong></p><ul><li>小厂可直接用 OSS 云服务，如阿里云 OSS 或腾讯云 OSS；</li><li>中大厂可基于 FastDFS、MinIO 等服务自建。</li></ul><p><strong>2. 超大文件上传</strong></p><table><thead><tr><th style="text-align:left;">方案</th><th style="text-align:left;">实现</th><th style="text-align:left;">优势</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>分片上传</strong></td><td style="text-align:left;">客户端切分成片 (1-10MB)，并行上传，服务端合并</td><td style="text-align:left;">突破单文件大小限制，并行加速</td></tr><tr><td style="text-align:left;"><strong>流式上传</strong></td><td style="text-align:left;">边读边传，不落本地磁盘</td><td style="text-align:left;">节省客户端内存</td></tr><tr><td style="text-align:left;"><strong>分段合并</strong></td><td style="text-align:left;">服务端接收分片，异步合并</td><td style="text-align:left;">避免长连接占用</td></tr></tbody></table><p><strong>3. 断点续传</strong></p><ol><li>客户端：记录已上传分片列表（localStorage/IndexedDB）；</li><li>上传前：请求服务端获取已上传分片列表；</li><li>上传时：只传缺失分片；</li><li>完成：服务端合并。</li></ol><p><strong>4. 避免重复文件存储</strong></p><ol><li><strong>客户端计算文件数字签名</strong>（采用 MD5、SHA 等算法）；</li><li>如果文件特别大，可按固定大小切片，针对每个切片取头部固定数量的字节生成签名（即<strong>分片哈希</strong>）；</li><li><strong>服务端查询文件哈希值是否存在</strong>：</li></ol><ul><li>存在：直接返回已有文件 URL（0 秒完成）；</li><li>不存在：执行正常上传。</li></ul><p><strong>哈希碰撞</strong>：碰撞概率极低，但不可不防——</p><ul><li>文件数字签名采用尽可能安全的哈希算法，如 SHA-256；</li><li>数字签名相同时再对比文件大小，大小不同一定不是同一文件；</li><li>还可以抽取文件的部分字节内容进行比对。</li></ul><p><strong>注意</strong>：需记录文件被引用次数，引用数为零时物理删除。文件哈希这种思路不仅可用于避免重复存储，也可用于<strong>秒传</strong>——发现上传的是重复文件，直接返回上传成功。</p><p><strong>5. 限流</strong></p><p>限流策略：</p><ul><li>单用户：10MB/s 或 100 个文件/小时；</li><li>单 IP：3 个并发上传；</li><li>单文件大小：100MB（图片）/1GB（视频）；</li><li>集群总带宽：1Gbps（Nginx 限速）。</li></ul><p><strong>实现</strong>：令牌桶/漏桶算法 + Redis 计数器。</p><p><strong>6. 性能设计</strong></p><table><thead><tr><th style="text-align:left;">优化点</th><th style="text-align:left;">方案</th><th style="text-align:left;">效果</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>分片并发</strong></td><td style="text-align:left;">3-5 片并行上传</td><td style="text-align:left;">带宽利用率提升</td></tr><tr><td style="text-align:left;"><strong>压缩传输</strong></td><td style="text-align:left;">Gzip 压缩文本文件</td><td style="text-align:left;">传输量减少 70%</td></tr><tr><td style="text-align:left;"><strong>CDN 加速</strong></td><td style="text-align:left;">上传域名走 CDN 动态加速</td><td style="text-align:left;">跨地域延迟降低</td></tr><tr><td style="text-align:left;"><strong>就近上传</strong></td><td style="text-align:left;">DNS 解析就近上传节点</td><td style="text-align:left;">减少网络往返</td></tr><tr><td style="text-align:left;"><strong>内存池</strong></td><td style="text-align:left;">复用缓冲区</td><td style="text-align:left;">GC 压力降低</td></tr></tbody></table><h4 id="🔬-扩展知识-1" tabindex="-1"><a class="header-anchor" href="#🔬-扩展知识-1"><span>🔬 扩展知识</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li><p>【L3】为什么大文件要用分片哈希？</p><p>全量文件哈希计算耗时随文件大小线性增长，按分片取头部固定字节生成签名可快速判重。</p><p>安全上应选 SHA-256 等抗碰撞算法，MD5 已不建议用于安全判重。</p></li><li><p>【L3】文件上传系统的容量与带宽怎么估算？</p><p>例如单文件上限 1GB、日活上传者 1 万、人均上传 100MB，日增存储约 1TB（3 副本则约 3TB）。</p><p>上传集群出口带宽需覆盖并发上传数 × 单用户限速，1000 路并发 × 10MB/s 约需 80Gbps，据此反推节点数。</p></li><li><p>【L3】为什么大文件要走直传架构？</p><p>大文件不应经应用服务器中转（带宽双倍占用、应用层成为吞吐瓶颈），应由服务端签发 STS 临时凭证或签名。</p><p>客户端直传 OSS，上传完成回调注册元数据，与云厂商 OSS 的 Web 端直传/Multipart Upload 模式一致。</p></li><li><p>【L3】文件类型校验的安全边界在哪里？</p><p>文件类型校验不能只信扩展名与 Content-Type（均可伪造），需检查文件魔数（头部字节）。</p><p>公网可访问的上传内容要接入病毒扫描与违规内容审核，防止上传通道成为恶意文件分发源。</p></li><li><p>【L4】分片合并失败与一致性怎么处理？</p><p>分片合并耗时长，应异步合并 + 任务表记录 + 失败重试；分片完整性以服务端记录为准，避免&quot;合并完成但分片缺失&quot;的幽灵文件。</p><p>自建分片上传的本质与云厂商 OSS 的 Multipart Upload API 一致，可参考其分片号、回调与断点协议设计。</p></li></ul></details><h4 id="🔀-发散问题-1" tabindex="-1"><a class="header-anchor" href="#🔀-发散问题-1"><span>🔀 发散问题</span></a></h4><ul><li><p><strong>Q：如何防止恶意用户刷上传带宽？</strong></p><p>→ 多维度限流：单用户限速/限文件数、单 IP 限并发、单文件大小上限、集群总带宽（Nginx 限速），用令牌桶/漏桶 + Redis 计数器实现。</p></li><li><p><strong>Q：秒传具体怎么实现？</strong></p><p>→ 客户端计算文件哈希先查服务端，命中则直接返回已有文件 URL（0 秒完成），只增加一次引用计数，不做物理存储。</p></li><li><p><strong>Q：哈希碰撞了怎么办？</strong></p><p>→ 碰撞概率极低但必须设防：用 SHA-256 等安全算法；签名相同时再比文件大小；必要时抽样部分字节比对。</p></li></ul><h3 id="【中等】如何设计一个单点登录系统-sso-⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】如何设计一个单点登录系统-sso-⭐⭐⭐⭐"><span>【中等】如何设计一个单点登录系统（SSO）？⭐⭐⭐⭐</span></a></h3><blockquote><p>🎯 目标等级：L2-L3 ｜ ⏱ 建议用时：15 min ｜ 🏷 标签：系统设计 / 认证</p></blockquote><h4 id="💎-关键结论-2" tabindex="-1"><a class="header-anchor" href="#💎-关键结论-2"><span>💎 关键结论</span></a></h4><p>SSO 核心是统一认证中心 + 可信凭证，子系统不存用户信息，只校验凭证。选型上，前后端分离/微服务用 JWT，传统 Web 用 CAS，第三方授权用 OAuth2.0；关键保障是凭证防篡改、登出同步、认证中心多活，避免单点故障。</p><h4 id="⚡-记忆卡片-2" tabindex="-1"><a class="header-anchor" href="#⚡-记忆卡片-2"><span>⚡ 记忆卡片</span></a></h4><ul><li><strong>口诀</strong>：统一认证、凭证可信、本地验签、黑名单登出</li><li><strong>关键词</strong>：认证中心 ／ JWT ／ CAS 票据 ／ Refresh Token ／ 黑名单</li><li><strong>链路</strong>：子系统跳转 → 认证中心登录 → 颁发凭证 → 本地验签免登 → 黑名单 + 通知登出</li></ul><h4 id="📖-核心知识-2" tabindex="-1"><a class="header-anchor" href="#📖-核心知识-2"><span>📖 核心知识</span></a></h4><p><strong>1. 核心组件</strong></p><table><thead><tr><th>组件</th><th>作用</th></tr></thead><tbody><tr><td>认证中心（SSO Server）</td><td>唯一登录入口，负责用户身份校验、颁发凭证、登出同步</td></tr><tr><td>子系统（SSO Client）</td><td>业务系统（如订单、商品、支付系统），依赖认证中心验证用户身份</td></tr><tr><td>凭证（Token/Ticket）</td><td>认证中心颁发的身份标识（如 JWT、ST 票），用于子系统校验</td></tr><tr><td>用户</td><td>访问各子系统的终端用户</td></tr></tbody></table><p><strong>2. 步骤一：选择 SSO 实现方案</strong></p><table><thead><tr><th>方案</th><th>核心逻辑</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>Token 方案（JWT）</strong></td><td>认证中心生成 JWT Token，子系统本地验签（无需回调认证中心）</td><td>前后端分离、微服务、跨域（APP / 小程序）</td></tr><tr><td><strong>CAS 协议（票据）</strong></td><td>子系统跳转认证中心登录，认证中心返回 ST 票，子系统回调认证中心验票</td><td>传统 Web 系统、需严格会话控制</td></tr><tr><td><strong>OAuth2.0（授权）</strong></td><td>子系统申请授权，认证中心颁发 Access Token，用于访问用户资源</td><td>第三方授权登录（如微信 / 支付宝登录）</td></tr></tbody></table><p><strong>3. 步骤二：设计凭证机制（凭证防篡改）</strong></p><ul><li><strong>JWT Token</strong>（推荐）： <ul><li>结构：Header（加密算法）+ Payload（用户 ID / 过期时间）+ Signature（签名）；</li><li>核心：子系统用公钥验签，无需调用认证中心，性能高；</li><li>防护：设置短过期时间（如 1 小时），配合刷新令牌（Refresh Token）续期，Token 不可篡改。</li></ul></li><li><strong>票据（CAS 方案）</strong>： <ul><li>TGT：用户登录后认证中心生成的会话凭证（存服务端）；</li><li>ST：子系统跳转时，认证中心基于 TGT 生成的一次性票据，子系统回调认证中心校验 ST 有效性。</li></ul></li></ul><p><strong>4. 步骤三：设计登录流程（以 JWT 为例）</strong></p><ol><li>用户访问子系统 A，未登录则跳转至认证中心；</li><li>用户在认证中心输入账号密码，校验通过后，认证中心生成 JWT Token（含用户 ID、过期时间），返回给用户；</li><li>用户携带 Token 访问子系统 A，子系统 A 验签通过后，建立本地会话，实现登录；</li><li>用户访问子系统 B，携带同一 Token，子系统 B 验签通过后，直接免登。</li></ol><p><strong>5. 步骤四：设计登出流程（关键防残留）</strong></p><ol><li>用户在任一子系统发起登出请求，跳转至认证中心；</li><li>认证中心处理：若用 JWT，将 Token 加入 Redis 黑名单（解决 JWT 无法主动销毁）；若用 CAS，销毁服务端 TGT 会话；</li><li>认证中心通知所有子系统销毁本地会话（如通过 MQ 推送登出消息）；</li><li>子系统校验 Token 时，先查黑名单，失效则拒绝访问。</li></ol><p><strong>6. 步骤五：核心防护设计（必做）</strong></p><ul><li><strong>防伪造</strong>：Token 签名加密（如 HS256/RSA），避免篡改；</li><li><strong>防过期</strong>：Refresh Token 机制，Token 过期后自动刷新；</li><li><strong>防跨域</strong>：配置 CORS 白名单，仅允许可信子系统访问；</li><li><strong>防重放</strong>：Token 加入 nonce 随机数，或设置极短过期时间；</li><li><strong>高可用</strong>：认证中心集群部署，Token 黑名单（Redis）做主从同步。</li></ul><h4 id="🔬-扩展知识-2" tabindex="-1"><a class="header-anchor" href="#🔬-扩展知识-2"><span>🔬 扩展知识</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li><p>【L3】JWT 无状态的代价是什么？</p><p>登出/踢人/改密无法立即生效，本质是用黑名单把无状态又变成了有状态。</p><p>黑名单 key 只存 jti 不存全量 Token，TTL 设为 Token 剩余有效期，控制 Redis 内存。</p></li><li><p>【L3】验签时为什么要给 exp 加容差？</p><p>时钟漂移：验签时 exp 判断加几秒容差（leeway），否则集群机器时钟不同步会导致 Token 忽有效忽失效。</p></li><li><p>【L4】单点登出为什么存在最终一致窗口？</p><p>MQ 通知各子系统销毁会话是异步的，存在秒级窗口；可接受则用短有效期 Token 兜底。</p><p>不可接受则子系统每次请求回调认证中心校验（牺牲性能换强控）。</p></li><li><p>【L4】JWT 与 CAS 两种方案怎么权衡，踩过什么坑？</p><table><thead><tr><th>维度</th><th>JWT 无状态</th><th>CAS 集中会话</th></tr></thead><tbody><tr><td>验签路径</td><td>验签无需回调认证中心，每请求省去一次远程调用（约 5~10ms）</td><td>每请求验票，认证中心成为性能瓶颈与单点</td></tr><tr><td>失效控制</td><td>无法即时废黜（依赖黑名单）</td><td>会话集中可控</td></tr><tr><td>高并发应对</td><td>子系统本地验签，短时抖动不影响存量会话</td><td>高并发下验票压力需集群抗</td></tr></tbody></table><p>曾有线上事故：认证中心单点宕机，所有子系统登录态校验失败，全站不可用 20 分钟——<strong>认证中心必须多活 + 子系统本地验签兜底</strong>。</p></li><li><p>【L4】集团级 SSO 的规模化怎么估算？</p><p>场景口径：集团 20 个子系统、Web + App + 小程序混合、日登录 500 万次、踢人 10 秒内生效。</p><p>选型：JWT + Refresh Token（App/小程序无法用 Cookie 共享），认证中心多活部署 + Redis 黑名单集群。</p><p>踢人靠黑名单 jti 秒级生效，子系统本地验签缓存 TTL 设 5~10 秒兜底。</p><p>登录 QPS ≈ 500 万/86400 × 峰值系数 ≈ 几百 QPS，两机房双活轻松承载。</p><p>关键设计：子系统对认证中心的依赖只有登录/刷新，验签本地完成，认证中心短时抖动不影响存量会话。</p></li></ul></details><h4 id="🔀-发散问题-2" tabindex="-1"><a class="header-anchor" href="#🔀-发散问题-2"><span>🔀 发散问题</span></a></h4><ul><li><p><strong>Q：JWT 方案下如何实现&quot;踢人下线&quot;？</strong></p><p>→ 把被踢用户的 jti 或 userId + 签发时间戳加入 Redis 黑名单（TTL = Token 剩余有效期），子系统验签后查黑名单；若子系统本地缓存了验签结果，需 MQ 广播失效事件，容忍秒级窗口。</p></li><li><p><strong>Q：跨域场景（<a href="http://app.xxx.com" target="_blank" rel="noopener noreferrer">app.xxx.com</a> 与 <a href="http://h5.xxx.com" target="_blank" rel="noopener noreferrer">h5.xxx.com</a>）如何共享登录态？</strong></p><p>→ 同主域用 Cookie <a href="http://domain=.xxx.com" target="_blank" rel="noopener noreferrer">domain=.xxx.com</a> 共享；跨主域只能走认证中心重定向（CAS 式）或 Token 通过 URL/PostMessage 传递后存本地，后者需防 URL 泄露（一次性 code 兑换）。</p></li><li><p><strong>Q：认证中心 QPS 怎么估算？</strong></p><p>→ JWT 方案下认证中心只承担登录/刷新请求（QPS = 登录频次，远低于业务 QPS）；CAS 方案要按全量请求验票估算，通常需本地 Session 缓存把验票频率降到会话级，否则认证中心会成为全链路瓶颈。</p></li><li><p><strong>Q：微信扫码登录和 SSO 是什么关系？</strong></p><p>→ 微信扫码属于第三方授权登录（OAuth2.0 授权码模式），可视为 SSO 体系中接入外部认证中心的一种形态，见本文档「如何实现微信扫码登录？」。</p></li></ul><h3 id="【中等】如何实现微信扫码登录-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】如何实现微信扫码登录-⭐⭐⭐"><span>【中等】如何实现微信扫码登录？⭐⭐⭐</span></a></h3><blockquote><p>🎯 目标等级：L2-L3 ｜ ⏱ 建议用时：15 min ｜ 🏷 标签：系统设计 / 第三方登录</p></blockquote><h4 id="💎-关键结论-3" tabindex="-1"><a class="header-anchor" href="#💎-关键结论-3"><span>💎 关键结论</span></a></h4><p>微信扫码登录本质是 OAuth2.0 授权码模式。微信官方网站应用登录：PC 端内嵌微信 qrconnect 授权二维码（携带 AppID 与 state），用户扫码确认授权后，微信将浏览器重定向回 <code>redirect_uri</code> 并携带一次性 <code>code</code>，后端用 code + AppSecret 换 AccessToken、拉取用户信息，最后颁发自己的 Session 或 JWT 完成登录。面经中广为流传的&quot;自建 UUID 二维码 + Redis 状态 + 前端轮询&quot;是通用扫码登录模型（适用于自建 App 扫码场景），与微信官方流程的差异见扩展知识。</p><h4 id="⚡-记忆卡片-3" tabindex="-1"><a class="header-anchor" href="#⚡-记忆卡片-3"><span>⚡ 记忆卡片</span></a></h4><ul><li><strong>口诀</strong>：画码、扫绑、轮询换、取信登</li><li><strong>关键词</strong>：UUID ／ openid ／ 授权码 code ／ AccessToken ／ 轮询</li><li><strong>链路</strong>：生成 UUID 二维码 → 扫码绑定 openid → 回调更新状态 → 轮询得 code → 换 Token → 颁发会话</li></ul><h4 id="📖-核心知识-3" tabindex="-1"><a class="header-anchor" href="#📖-核心知识-3"><span>📖 核心知识</span></a></h4><blockquote><p>说明：下文按面试常考的<strong>通用扫码登录模型</strong>（服务端自生成 UUID + Redis 记状态 + 前端轮询）展开三阶段；微信官方网站应用登录实际采用 qrconnect 授权页 + 浏览器重定向回传 code 的方式，无服务器间回调，精确差异见 🔬 扩展知识。</p></blockquote><p><strong>1. 第一阶段：准备阶段（生成二维码）</strong></p><p>目标：让 PC 网页拿到一个<strong>唯一标识本次登录请求的 UUID</strong>，并把它画成二维码。要点：<strong>网页后端生成唯一 ID，Redis 记下它状态，URL 塞进二维码里</strong>。</p><ol><li><strong>准备材料</strong>：第三方网站需要在<strong>微信开放平台</strong>提前注册，拿到 <code>AppID</code> 和 <code>AppSecret</code>；</li><li><strong>请求二维码</strong>：用户点击&quot;微信登录&quot;，PC 端网页向后端请求一个二维码；</li><li><strong>生成 UUID</strong>：第三方服务器生成一个<strong>唯一的、临时的 UUID</strong>（或称 state/ticket），并把该 UUID 的状态（如：未扫描）存到 Redis；</li><li><strong>返回二维码</strong>：服务器把包含 <code>AppID</code>、<code>redirect_uri</code>（回调地址）和该 <code>UUID</code> 的信息包装成一个 URL，返回给前端画成二维码。</li></ol><p><strong>2. 第二阶段：扫描阶段（扫码确认）</strong></p><p>目标：用户扫码确认，让微信服务器知道&quot;这个 UUID 被这个微信号授权了&quot;。要点：<strong>手机扫码读 UUID，微信确认发授权，绑定 UUID 和 openid</strong>。</p><ol><li><strong>扫码</strong>：用户打开微信扫一扫，微信 APP 解析出二维码中的 <code>UUID</code>；</li><li><strong>跳转授权</strong>：微信 APP 将该 <code>UUID</code> 和用户身份信息（<code>openid</code>）发送给<strong>微信服务器</strong>，并展示授权页面（&quot;XX 应用请求获取你的昵称、头像&quot;）；</li><li><strong>用户确认</strong>：用户点击&quot;确认登录&quot;；</li><li><strong>记录绑定</strong>：微信服务器记录 <code>UUID</code> 与 <code>openid</code> 的绑定关系，并通过回调通知第三方服务器该 <code>UUID</code> 已被授权。</li></ol><p><strong>3. 第三阶段：回调阶段（登录成功）</strong></p><p>目标：PC 网页得知授权成功，拿到用户信息，完成登录。要点：<strong>前端一直轮询，发现授权赶紧换，换到 Token 取信息，生成票据登录</strong>。</p><ol><li><strong>轮询查状态</strong>：扫码的同时，PC 前端一直在<strong>轮询</strong>后端接口：&quot;我这个 <code>UUID</code> 的状态变了吗？&quot;；</li><li><strong>状态变更</strong>：微信服务器通知授权成功后，第三方服务器把 Redis 中该 <code>UUID</code> 的状态更新为&quot;已授权&quot;，并准备好 <code>code</code>（授权码）；</li><li><strong>换取 Token</strong>：PC 前端轮询到&quot;已授权&quot;，后端立即使用 <code>code</code> + <code>AppSecret</code> 去微信服务器换取 <code>AccessToken</code>；</li><li><strong>获取用户信息</strong>：用 <code>AccessToken</code> 调用微信接口，获取用户 <code>openid</code>、昵称、头像等信息；</li><li><strong>登录成功</strong>：后端用这些信息生成自己系统的 <code>Session</code> 或 <code>JWT Token</code> 返回给前端，登录完成。</li></ol><h4 id="🔬-扩展知识-3" tabindex="-1"><a class="header-anchor" href="#🔬-扩展知识-3"><span>🔬 扩展知识</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li><p>【L3】为什么用 code 换 Token，而不是直接把 Token 返回给前端？</p><p>code 是一次性、短时效的前通道凭证。</p><p>AccessToken 由后端用 code + AppSecret 通过服务端通道换取，即使 code 被截获，没有 AppSecret 也换不到 Token，避免敏感凭证暴露在前端。</p></li><li><p>【L3】微信官方扫码流程与自建扫码模型差在哪？</p><p>微信 qrconnect 模式下二维码由微信托管（内容是授权 URL，携带 AppID/state/redirect_uri）。</p><p>用户扫码确认后微信以 302 将<strong>浏览器</strong>重定向到 <code>redirect_uri?code=xxx&amp;state=xxx</code>（前通道回传），并非&quot;微信服务器回调第三方服务器&quot;；前端从重定向结果拿 code 交后端换 Token。</p><p>&quot;UUID 存 Redis + 前端轮询状态&quot;是自建扫码登录（如自家 App 扫 PC 码）的通用模型，两者混谈会被面试官抓住追问。</p></li><li><p>【L3】轮询 vs 长连接怎么选？</p><p>轮询实现简单、兼容性好（间隔 1~2 秒并限制总时长），UUID 状态存 Redis 并设置 TTL（如 5 分钟）。</p><p>大规模场景可升级为 WebSocket/SSE 推送，减少无效轮询请求。</p></li><li><p>【L4】扫码登录有哪些安全要点？</p><p>UUID 必须随机不可预测，防止他人轮询劫持扫码结果。</p><p>redirect_uri 需在开放平台配置白名单校验，防止授权码被钓鱼到恶意站点。</p><p>OAuth2.0 实践中还应带 state 参数防 CSRF。</p></li></ul></details><h4 id="🔀-发散问题-3" tabindex="-1"><a class="header-anchor" href="#🔀-发散问题-3"><span>🔀 发散问题</span></a></h4><ul><li><p><strong>Q：二维码超时未被扫描怎么办？</strong></p><p>→ UUID 状态设置 TTL，过期后端置为失效，前端提示&quot;二维码已失效&quot;并提供刷新按钮，重新生成 UUID 与二维码。</p></li><li><p><strong>Q：扫码登录成功后，PC 端与移动端如何维持统一登录态？</strong></p><p>→ PC 端登录成功后颁发自有 Session/JWT，后续多端登录态维持就是 SSO 问题，见本文档「如何设计一个单点登录系统（SSO）？」。</p></li><li><p><strong>Q：授权码模式和隐式模式（直接返回 Token）有什么区别？</strong></p><p>→ 授权码模式的 Token 走后端通道换取，更安全；OAuth2.0 当前最佳实践推荐授权码模式，不推荐把 Token 直接返回给前端的隐式模式。</p></li></ul><h3 id="【中等】如何设计一个短链服务-⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】如何设计一个短链服务-⭐⭐⭐⭐"><span>【中等】如何设计一个短链服务？⭐⭐⭐⭐</span></a></h3><blockquote><p>🎯 目标等级：L2-L3 ｜ ⏱ 建议用时：15 min ｜ 🏷 标签：系统设计 / 短链</p></blockquote><h4 id="💎-关键结论-4" tabindex="-1"><a class="header-anchor" href="#💎-关键结论-4"><span>💎 关键结论</span></a></h4><p>短链服务三个字：生成、存储、重定向。主流方案是自增 ID 经发号器生成后转 62 进制短码，写 MySQL 读 Redis 缓存，用 302 跳转保留点击统计能力；典型读多写少，缓存可挡 99% 请求，布隆过滤器防缓存穿透。</p><h4 id="⚡-记忆卡片-4" tabindex="-1"><a class="header-anchor" href="#⚡-记忆卡片-4"><span>⚡ 记忆卡片</span></a></h4><ul><li><strong>口诀</strong>：发号取数、62 转码、缓存挡读、302 统计</li><li><strong>关键词</strong>：发号器 ／ 62 进制 ／ Redis 缓存 ／ 302 ／ 布隆过滤器</li><li><strong>链路</strong>：长链 → 发号器 ID → 62 进制短码 → 写 MySQL → 读缓存 → 302 跳转</li></ul><h4 id="📖-核心知识-4" tabindex="-1"><a class="header-anchor" href="#📖-核心知识-4"><span>📖 核心知识</span></a></h4><blockquote><p>要点：生成、存储、重定向。</p></blockquote><p><strong>1. 生成：长链变短码</strong></p><ul><li><strong>哈希</strong>：对长链接进行哈希（如 <code>MD5</code>），得到一个 32 位字符串；</li><li><strong>自增 ID</strong>：用一个中心服务（如 Redis）生成自增数字 ID（如：100001、100002）。</li></ul><p>短链不够短可采用转码：把数值转成 <strong>62 进制</strong>（用光所有数字 + 大小写字母）。例如 ID <code>100001</code> → 短码 <code>aB3</code>。</p><p><strong>2. 存储：写 DB，读 Cache</strong></p><ul><li><strong>写路径</strong>：<code>长链接 -&gt; 发号器拿 ID -&gt; 转短码 -&gt; 存 MySQL（落盘）</code>；</li><li><strong>读路径（关键）</strong>：第一步查 <strong>Redis</strong>，有就直接用；Redis 没有查 <strong>MySQL</strong>；查到后<strong>回写 Redis</strong>，下次就快了。</li></ul><p><strong>3. 重定向：301 还是 302？</strong></p><ul><li><strong>301（永久）</strong>：浏览器会记住，下次不再访问短链服务器；缺点是<strong>没法统计点击次数</strong>；</li><li><strong>302（临时）</strong>：每次都先找短链服务器再跳转；优点是<strong>可以精确计数</strong>（点了几次、谁点的）。</li><li><strong>结论：推荐 302</strong>，为了数据和灵活性。</li></ul><p><strong>4. 性能设计</strong></p><ul><li><strong>缓存</strong>：缓存挡住 99% 的读请求，不让流量打垮 DB；</li><li><strong>预发号</strong>：短链生成服务不要每次都找发号器，而是一次性生成一批短链（比如 1000 个）放本地内存，用完了再拿，减少对发号器的压力；</li><li><strong>布隆过滤器</strong>：恶意输入不存在的短码（如 <code>aaaaaa</code>）会造成<strong>缓存穿透</strong>，布隆过滤器像前置&quot;筛查员&quot;，快速判断短码<strong>肯定不存在</strong>并直接拦截，保护后端。</li></ul><h4 id="🔬-扩展知识-4" tabindex="-1"><a class="header-anchor" href="#🔬-扩展知识-4"><span>🔬 扩展知识</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li><p>【L3】6 位短码的容量空间够用多久？</p><p>62 进制 6 位短码空间 = 62^6 ≈ 568 亿；日生成 100 万短链可支撑约 155 年，日生成 1000 万约 15 年，不够则升 7 位。</p></li><li><p>【L3】发号器怎么做高可用？</p><p>号段模式：每台发号实例批量取号（如每次 1000 个），DB 只存 max_id，多实例取不同号段防冲突。</p><p>或用 Redis INCR 但需解决持久化。</p></li><li><p>【L3】哈希短码的冲突怎么处理？</p><p>MD5 取前 6 位冲突概率高，需查库判重后重算或拼接重试；自增 ID 转 62 进制无冲突，是更稳的选择。</p></li><li><p>【L4】短码怎么防枚举与防爬？</p><p>自增 ID 可被顺序枚举，可对 ID 做位运算混淆或加随机盐后再转 62 进制。</p><p>同时监控异常短码扫描行为。</p></li><li><p>【L4】哈希方案与自增 ID 方案怎么权衡？</p><table><thead><tr><th>维度</th><th>哈希取短</th><th>自增 ID 转 62 进制</th></tr></thead><tbody><tr><td>中心化依赖</td><td>无需中心化发号</td><td>发号器是单点依赖，需号段模式消除</td></tr><tr><td>冲突处理</td><td>冲突处理复杂（查库重试），高并发下冲突重试放大延迟</td><td>无冲突</td></tr></tbody></table><p>曾有线上事故：用 MD5 前 6 位做短码未做冲突检测，两条不同长链映射同一短码，导致营销活动跳转到错误落地页——<strong>哈希取短必须判重，或直接选自增 ID 方案</strong>。</p></li><li><p>【L4】短链服务有哪些失效场景，大促规模怎么估算？</p><p>失效场景：布隆过滤器存在误判率（如 1% 误杀真实短码），需控制容量与哈希函数数量。</p><p>短链服务典型读多写少（100:1 以上），读缓存失效风暴时需互斥重建防击穿。</p><p>大促示例（日生成 500 万、峰值 5 万 TPS 生成、读峰值 20 万 QPS、防枚举）：</p><table><thead><tr><th>环节</th><th>做法</th></tr></thead><tbody><tr><td>发号</td><td>发号器号段模式多实例（每实例每次取 1 万号段，DB 压力仅几百 QPS）</td></tr><tr><td>防枚举</td><td>自增 ID 先乘一个大质数再异或固定盐后转 62 进制，短码与 ID 无单调关系</td></tr><tr><td>读路径</td><td>Redis 集群承载（20 万 QPS 约 2~3 个分片实例），长 TTL 命中率 99%+，DB 只做兜底</td></tr><tr><td>生成峰值</td><td>用 MQ 削峰异步落库，同步只返回预取号段生成的短码</td></tr></tbody></table></li></ul></details><h4 id="🔀-发散问题-4" tabindex="-1"><a class="header-anchor" href="#🔀-发散问题-4"><span>🔀 发散问题</span></a></h4><ul><li><p><strong>Q：短链服务读 QPS 10 万、缓存命中率 99%，DB 要承受多少？如何再降？</strong></p><p>→ 回源约 1000 QPS，单 MySQL 实例可扛；若命中率下降可加本地缓存（短码映射几乎不变，本地缓存命中率极高）再降一个数量级。关键设计：短码 → 长链是不可变映射，缓存可设长 TTL 甚至永不过期。</p></li><li><p><strong>Q：如何统计点击数据而不拖慢跳转？</strong></p><p>→ 302 返回与统计异步解耦：跳转响应先发，点击事件丢 MQ 异步落库/实时计算；统计分析走独立链路（如 Flink 实时聚合），不在跳转主路径同步写 DB。</p></li><li><p><strong>Q：发号器实例宕机，预取的号段会怎样？</strong></p><p>→ 号段在实例内存，宕机丢未用完的号段（如 1000 个），ID 出现空洞但不重复——号段模式天然接受空间浪费换可用性；双 Buffer 下另一个号段仍可用，对业务透明。</p></li></ul><h3 id="【困难】如何设计一个-feed-流系统-朋友圈-微博-⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【困难】如何设计一个-feed-流系统-朋友圈-微博-⭐⭐⭐⭐"><span>【困难】如何设计一个 Feed 流系统（朋友圈/微博）？⭐⭐⭐⭐</span></a></h3><blockquote><p>🎯 目标等级：L3-L4 ｜ ⏱ 建议用时：20 min ｜ 🏷 标签：系统设计 / Feed 流</p></blockquote><h4 id="💎-关键结论-5" tabindex="-1"><a class="header-anchor" href="#💎-关键结论-5"><span>💎 关键结论</span></a></h4><p>Feed 流本质是读写扩散的权衡：推模式发帖时写入粉丝收件箱，读快写慢，适合普通用户；拉模式读时合并，写快读慢，适合大 V；业界主流是推拉结合。存储用 Redis ZSet 存最近 N 条帖子 ID，历史落盘，读时批量回填内容。</p><h4 id="⚡-记忆卡片-5" tabindex="-1"><a class="header-anchor" href="#⚡-记忆卡片-5"><span>⚡ 记忆卡片</span></a></h4><ul><li><strong>口诀</strong>：小粉推、大 V 拉、读时合并、ZSet 存</li><li><strong>关键词</strong>：写扩散 ／ 读扩散 ／ 推拉结合 ／ ZSet ／ 批量回填</li><li><strong>链路</strong>：发帖 → 扩散决策（推/拉）→ 收件箱 ZSet → 读时合并 → ID 回填内容</li></ul><h4 id="📖-核心知识-5" tabindex="-1"><a class="header-anchor" href="#📖-核心知识-5"><span>📖 核心知识</span></a></h4><p>Feed 流核心问题：用户关注 N 个人，如何快速拉出按时间排序的内容流？本质是<strong>读写扩散的权衡</strong>。</p><p><strong>1. 三种模式对比</strong></p><table><thead><tr><th style="text-align:left;">模式</th><th style="text-align:left;">原理</th><th style="text-align:left;">写开销</th><th style="text-align:left;">读开销</th><th style="text-align:left;">适用</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>推模式（写扩散）</strong></td><td style="text-align:left;">发帖时写入所有粉丝的收件箱</td><td style="text-align:left;">高（粉丝数倍数）</td><td style="text-align:left;">低（直接读自己的箱子）</td><td style="text-align:left;">粉丝数小的普通用户</td></tr><tr><td style="text-align:left;"><strong>拉模式（读扩散）</strong></td><td style="text-align:left;">读时遍历关注人的发件箱合并</td><td style="text-align:left;">低</td><td style="text-align:left;">高（关注数倍数）</td><td style="text-align:left;">大 V（千万粉丝）</td></tr><tr><td style="text-align:left;"><strong>推拉结合</strong></td><td style="text-align:left;">普通用户推，大 V 拉，读时合并</td><td style="text-align:left;">中</td><td style="text-align:left;">中</td><td style="text-align:left;">业界主流（微博）</td></tr></tbody></table><p><strong>量化选型</strong>：某用户 100w 粉丝，每天发 10 条 → 纯推模式日写 1000w 条，不可接受；改用拉模式后只在粉丝读时合并。</p><p><strong>2. 存储设计</strong></p><ul><li>收件箱/发件箱：Redis ZSet（score = 发帖时间戳，member = 帖子 ID），只存最近 N 条（如 1000）；历史数据落 MySQL/HBase；</li><li>帖子内容单独存储（帖表），Feed 流只存 ID，读时批量回填（注意用 batchGet 避免 N+1）。</li></ul><p><strong>3. 其他要点</strong></p><ul><li>排序策略：时间序 vs 算法推荐；</li><li>幂等：客户端生成帖子 ID 防重发；</li><li>删帖：需异步清理已扩散的收件箱（或读时过滤已删帖子）。</li></ul><h4 id="🔬-扩展知识-5" tabindex="-1"><a class="header-anchor" href="#🔬-扩展知识-5"><span>🔬 扩展知识</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li><p>【L3】推拉的分界线怎么定？</p><p>按&quot;写放大 vs 读放大&quot;成本平衡——某用户粉丝 F、日发帖 P，推成本 = F×P 次写/天；关注 K 人的用户拉成本 = K 次合并/刷。</p><p>一般粉丝超万级转拉模式，具体阈值用实际读写 QPS 比例压测校准，且分界线应可配置化动态调整。</p></li><li><p>【L3】Feed 翻页为什么用游标分页？</p><p>以最后一条帖子的时间戳/ID 作为游标，向历史库（MySQL/HBase）拉取更早数据。</p><p>Redis 只承担&quot;最新一页&quot;的热读，历史读走冷存储，避免 ZSet 无限膨胀。</p></li><li><p>【L4】Feed 怎么叠加个性化推荐排序？</p><p>读时先拉候选集（收件箱 + 大 V 发件箱合并，取最近几百条 ID），再调推荐服务打分重排（召回 + 粗排 + 精排分层）。</p><p>打分服务超时需降级为时间序兜底，不能阻塞 Feed 返回。</p></li><li><p>【L4】推模式与拉模式各自的代价是什么？</p><table><thead><tr><th>模式</th><th>代价</th><th>失效场景</th></tr></thead><tbody><tr><td>推模式</td><td>写放大（粉丝数倍数）</td><td>大 V 发帖一条写百万次，纯推模式在大 V 场景必然失效</td></tr><tr><td>拉模式</td><td>读放大（关注数倍数）</td><td>用户关注 500 人时每次刷 Feed 要合并 500 个列表，读 RT 不可接受</td></tr></tbody></table><p>推拉结合的分界线（如粉丝 &gt; 1 万走拉）需根据实际读写比例压测定，而非拍脑袋。</p></li></ul></details><h4 id="🏭-实战场景-1" tabindex="-1"><a class="header-anchor" href="#🏭-实战场景-1"><span>🏭 实战场景</span></a></h4><details class="hint-container details"><summary>详情</summary><p><strong>朋友圈类 Feed 场景</strong></p><p>场景：用户平均 300 好友（双向关注、无大 V 问题），DAU 1 亿，日发帖 5000 万条，要求刷 Feed P99 &lt; 200ms。</p><p>设计要点：好友数小（300）且无超大 V，写扩散可接受——每条帖子平均扩散 300 次写，日写量 5000 万 × 300 = 150 亿次。</p><p>峰值约 50 万写 QPS，需 Kafka 削峰 + Redis 集群（分片）承载；读路径直接取自己收件箱 ZSet，单次读取 O(1) 命令，P99 可控。</p><p>权衡点：若写集群成本过高，可退为&quot;活跃用户推、休眠用户拉&quot;——发帖时只扩散给近 30 天活跃好友，大幅削减无效写。</p><p><strong>行业教训</strong>：某社区纯推模式上线，千万粉大 V 一条帖子触发千万次 Redis 写入，收件箱写队列积压数小时——<strong>写扩散必须有粉丝数上限</strong>。</p></details><h4 id="⚠️-常见误区-1" tabindex="-1"><a class="header-anchor" href="#⚠️-常见误区-1"><span>⚠️ 常见误区</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li>❌ &quot;Feed 流一律用推模式，读性能最好&quot; → 大 V 发帖一次写百万粉丝收件箱，写放大会打垮存储，必须对大 V 切换拉模式。</li><li>❌ &quot;收件箱里直接存帖子内容，读起来省事&quot; → 扩散会让内容被复制千万份，存储爆炸且更新困难，应只存帖子 ID，读时批量回填。</li><li>❌ &quot;读扩散慢就多加机器&quot; → 读 RT 随关注数线性增长，关注 500 人就要合并 500 个列表，单请求串行合并的代价加机器解决不了，需并行合并 + 超时截断。</li></ul></details><h4 id="🔀-发散问题-5" tabindex="-1"><a class="header-anchor" href="#🔀-发散问题-5"><span>🔀 发散问题</span></a></h4><ul><li><p><strong>Q：用户关注太多导致 Feed 读取超时怎么办？</strong></p><p>→ 拉模式并行合并 + 超时截断（时限内返回已合并的 Top 部分）；或限制有效关注数、只拉取近期活跃关注者的发件箱。</p></li><li><p><strong>Q：删帖后已扩散到百万收件箱的引用怎么清理？</strong></p><p>→ 同步清理会被扩散量拖垮，应异步任务清理；清理完成前读时过滤已删帖子兜底。</p></li><li><p><strong>Q：Feed 流存储和 IM 消息存储有什么共性？</strong></p><p>→ 都是&quot;时间线索引 + ID 回填写&quot;模型，用 ZSet/列表存 ID、读时回填内容；IM 还多了会话级 seq 保序与双向扩散问题，见本文档「如何设计一个 IM 即时通讯系统？」。</p></li></ul><h3 id="【困难】如何设计一个-im-即时通讯系统-⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【困难】如何设计一个-im-即时通讯系统-⭐⭐⭐⭐"><span>【困难】如何设计一个 IM 即时通讯系统？⭐⭐⭐⭐</span></a></h3><blockquote><p>🎯 目标等级：L3-L4 ｜ ⏱ 建议用时：20 min ｜ 🏷 标签：系统设计 / IM</p></blockquote><h4 id="💎-关键结论-6" tabindex="-1"><a class="header-anchor" href="#💎-关键结论-6"><span>💎 关键结论</span></a></h4><p>IM 设计抓四条线：长连接网关无状态水平扩容做接入；ACK + 客户端 msgId + 会话级 seq 保证不丢、不重、不乱序；小群写扩散、大群读扩散；离线消息落库加厂商通道推送。单机网关可撑 10~20 万连接，存储按会话分库分表。</p><h4 id="⚡-记忆卡片-6" tabindex="-1"><a class="header-anchor" href="#⚡-记忆卡片-6"><span>⚡ 记忆卡片</span></a></h4><ul><li><strong>口诀</strong>：长连接、ACK 认、seq 序、小推大拉</li><li><strong>关键词</strong>：长连接网关 ／ ACK ／ msgId ／ seq ／ 读写扩散</li><li><strong>链路</strong>：客户端长连 → 网关路由 → 落库 + ACK → 收件箱扩散 → 离线推送</li></ul><h4 id="📖-核心知识-6" tabindex="-1"><a class="header-anchor" href="#📖-核心知识-6"><span>📖 核心知识</span></a></h4><p><strong>1. 整体架构</strong></p><p>接入层（长连接网关）→ 逻辑层（消息路由/会话）→ 存储层（消息库/离线库）+ 离线推送。</p><p><strong>2. 接入层设计</strong></p><ul><li>长连接选型：WebSocket / TCP 自定义协议（Netty）；心跳保活（30s）检测断连；</li><li>连接网关无状态水平扩容，维护 userId → 连接所在网关的映射（存 Redis/注册中心），消息路由靠它找到目标用户的连接。</li></ul><p><strong>3. 消息可靠性（不丢、不重、不乱序）</strong></p><ul><li><strong>不丢</strong>：发送方 → 服务器 ACK 确认机制，未 ACK 则重发；服务器 → 接收方同样 ACK；服务器落库成功后再 ACK 发送方；</li><li><strong>不重</strong>：客户端生成全局唯一 msgId（会话 ID + 自增序号），服务端去重；</li><li><strong>不乱序</strong>：每个会话维护自增 seq（Redis INCR 或发号器），客户端按 seq 排序；断线重连后用本地最大 seq 拉取增量补齐。</li></ul><p><strong>4. 消息存储与扩散</strong></p><ul><li><strong>单聊/小群（写扩散）</strong>：消息写入收发双方的会话索引（inbox），群成员少时逐人写；</li><li><strong>大群（读扩散）</strong>：消息只写群消息表，成员读时拉取 + 记录个人已读位点，避免百万人群写扩散爆炸；</li><li>消息库按会话维度分库分表（uid hash）；历史消息归档冷存储。</li></ul><p><strong>5. 离线推送</strong></p><p>用户不在线时消息存离线库，同时通过厂商通道（APNs/华为/小米）推送唤醒通知；上线后拉取离线消息。</p><h4 id="🔬-扩展知识-6" tabindex="-1"><a class="header-anchor" href="#🔬-扩展知识-6"><span>🔬 扩展知识</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li><p>【L3】单机长连接网关能支撑多少连接？</p><p>单机长连接网关基于 Netty 可支撑 10~20 万连接（受文件描述符与内存限制，每连接内存开销几十 KB）。</p><p>千万在线需百台级网关集群。</p></li><li><p>【L3】消息 seq 的发放为什么必须中心化？</p><p>会话级 seq 要用 Redis INCR 等中心化发号器且按会话维度。</p><p>用网关单机自增，网关重启后 seq 重复会导致客户端消息乱序重排。</p></li><li><p>【L4】大群消息的扩散模式怎么选，还有哪些失效场景？</p><p>百万人群若用写扩散，一条消息写百万条 inbox，写放大不可承受，必须读扩散 + 个人已读位点。</p><p>厂商推送通道有配额与延迟（秒~分钟级），重要消息需多通道冗余。</p></li></ul></details><h4 id="🏭-实战场景-2" tabindex="-1"><a class="header-anchor" href="#🏭-实战场景-2"><span>🏭 实战场景</span></a></h4><details class="hint-container details"><summary>详情</summary><p><strong>企业 IM 消息系统</strong></p><p>场景：500 万员工同时在线（工作日早高峰 9 点集中上线），单聊占 70%、千人群占 5%，要求消息端到端延迟 P99 &lt; 500ms、不丢不乱序。</p><p>接入层：500 万连接 / 单机 10 万 ≈ 50 台网关（预留 30% 冗余），早高峰重连风暴需客户端指数退避 + 服务端渐进注册。</p><p>扩散策略：单聊写扩散（收发双方 inbox 各写一条，写放大 2 倍可接受）；千人群用读扩散（消息只写群表，成员拉取 + 个人已读位点）。</p><p>若千人群写扩散，一条消息写 1000 条，早高峰必崩。</p><p>顺序与不丢：seq 用 Redis INCR 按会话发号，msgId 客户端生成防重；消息落库成功后再 ACK 发送方，保证不丢。</p><p><strong>生产事故教训</strong>：曾有线上事故——群消息 seq 用单机自增，网关重启后 seq 重复，客户端消息乱序重排。<strong>seq 必须用中心化发号器（Redis INCR）且按会话维度</strong>。</p></details><h4 id="⚠️-常见误区-2" tabindex="-1"><a class="header-anchor" href="#⚠️-常见误区-2"><span>⚠️ 常见误区</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li>❌ &quot;消息发出去就行，不用 ACK&quot; → 网络抖动与客户端崩溃都会导致消息丢失，必须双向 ACK + 未确认重发，服务端落库成功才能 ACK 发送方。</li><li>❌ &quot;用服务端生成的消息 ID 就能同时保证去重和顺序&quot; → 重发时服务端会生成新 ID，无法去重；应由客户端生成唯一 msgId 供服务端去重，顺序由独立的会话级 seq 保证。</li><li>❌ &quot;百万人群用写扩散也没问题，就是多写点&quot; → 一条消息写百万条 inbox，写放大直接打垮存储与写链路，大群必须读扩散。</li></ul></details><h4 id="🔀-发散问题-6" tabindex="-1"><a class="header-anchor" href="#🔀-发散问题-6"><span>🔀 发散问题</span></a></h4><ul><li><p><strong>Q：消息已读状态怎么设计？</strong></p><p>→ 不逐条标记已读，只存会话级&quot;已读位点&quot;（已读到的最大 seq），未读数 = 最新 seq - 已读位点；群已读回执（如钉钉）是例外，需单独存储已读成员位图，成本高，仅小群可用。</p></li><li><p><strong>Q：网关重启时如何做到连接不丢消息？</strong></p><p>→ 客户端断线重连携带本地最大 seq 向新网关拉取增量（写扩散下消息已落库）；服务端连接路由表（userId → 网关）随连接迁移更新；核心是消息落库与 ACK 解耦，重连可补拉。</p></li><li><p><strong>Q：IM 消息存储量如何估算？</strong></p><p>→ 单条消息约 200~500 字节，日活千万、人均 50 条 → 日增约 5 亿条 / 100~250GB，一年数十 TB；需按会话分库分表 + 半年以上消息归档冷存储（对象存储），在线库只保热数据。</p></li><li><p><strong>Q：IM 的时间线存储和 Feed 流有什么共性？</strong></p><p>→ 都是&quot;按会话/用户存 ID 索引 + 读时回填&quot;，都需要冷热分层；Feed 流还需处理读写扩散的分界线，见本文档「如何设计一个 Feed 流系统（朋友圈/微博）？」。</p></li></ul><h3 id="【困难】如何设计一个订单系统-⭐⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【困难】如何设计一个订单系统-⭐⭐⭐⭐⭐"><span>【困难】如何设计一个订单系统？⭐⭐⭐⭐⭐</span></a></h3><blockquote><p>🎯 目标等级：L3-L4 ｜ ⏱ 建议用时：20 min ｜ 🏷 标签：系统设计 / 交易</p></blockquote><h4 id="💎-关键结论-7" tabindex="-1"><a class="header-anchor" href="#💎-关键结论-7"><span>💎 关键结论</span></a></h4><p>订单系统核心是状态机 + 快照 + 分片：状态变更必须带前置条件更新防非法流转，下单时快照商品名与价格隔离后续改价，按买家 ID 分库分表支撑 C 端查询，卖家多维查询靠 ES 异构索引，一致性靠事件驱动 + 对账修复，不追求强一致。</p><h4 id="⚡-记忆卡片-7" tabindex="-1"><a class="header-anchor" href="#⚡-记忆卡片-7"><span>⚡ 记忆卡片</span></a></h4><ul><li><strong>口诀</strong>：状态机管流转、快照锁价格、买家分片、ES 查卖家、对账兜底</li><li><strong>关键词</strong>：状态机 ／ 订单快照 ／ 买家 ID 分片 ／ 异构索引 ／ 事件驱动对账</li><li><strong>链路</strong>：建单（快照 + 预占库存）→ 支付回调异步 → 状态机流转 → 买家分片查 / ES 多维查 → 对账修复</li></ul><h4 id="📖-核心知识-7" tabindex="-1"><a class="header-anchor" href="#📖-核心知识-7"><span>📖 核心知识</span></a></h4><p><strong>1. 订单状态机（核心）</strong></p><ul><li>主状态：待支付 → 已支付 → 待发货 → 已发货 → 已完成；分支：已取消、退款中；</li><li>所有状态变更必须<strong>带条件更新</strong>（<code>UPDATE ... WHERE status = 前置状态</code>）+ 状态机校验，拒绝非法跳转；状态变更流水表完整留痕。</li></ul><p><strong>2. 数据模型设计</strong></p><ul><li>主单/子单拆分：一次下单多商家/多仓拆为多个子单，各自履约；</li><li><strong>订单快照</strong>：商品名称/价格/优惠在下单时快照进订单，后续商品改价不影响历史订单（避免依赖商品表）；</li><li>垂直拆表：订单主表 + 订单明细 + 支付单 + 物流单，避免大宽表。</li></ul><p><strong>3. 性能与存储</strong></p><ul><li>分库分表：按买家 ID 分片（C 端查询主场景）；卖家维度查询同步到 ES 异构索引；</li><li>冷热分离：三个月内热单在在线库，历史单归档到历史库/数仓，在线库保持小体量；</li><li>写优化：下单链路同步只做最少动作（建单 + 预占库存），支付回调、通知、积分全部异步化。</li></ul><p><strong>4. 一致性与兜底</strong></p><ul><li>幂等：下单幂等键、支付回调幂等（见《功能设计面试》『如何避免用户重复下单』『如何解决订单重复支付情况』）；</li><li>与库存/优惠/支付的状态一致性靠<strong>事件驱动 + 对账修复</strong>，不追求分布式事务强一致；</li><li>超时未支付自动取消：延迟消息 + 扫表兜底（见《功能设计面试》『如何实现一个订单超时取消功能？』）。</li></ul><h4 id="🔬-扩展知识-7" tabindex="-1"><a class="header-anchor" href="#🔬-扩展知识-7"><span>🔬 扩展知识</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li><p>【L3】订单快照的代价值不值得付？</p><p>订单快照避免历史单受商品改价影响，代价是存储冗余（快照字段约占单量 30%）与下单时多一次商品查询。</p><p>相比改价引发的资损与客诉，这是必须付的成本。</p></li><li><p>【L3】下单写路径怎么优化？</p><p>下单同步路径只做建单 + 预占库存，RT 控制在 50ms 内；支付回调、通知、积分、风控全部异步化。</p><p>DB 单实例写入约 5000 TPS 是常见瓶颈，大促前必须压测 + MQ 削峰。</p></li><li><p>【L4】订单分片键怎么选？</p><table><thead><tr><th>分片方案</th><th>做法</th><th>代价</th></tr></thead><tbody><tr><td>按买家 ID 分片</td><td>对 C 端查询友好</td><td>卖家查单困难，需 ES 异构索引（引入同步延迟与运维成本）</td></tr><tr><td>基因法分片</td><td>把卖家信息编入订单号</td><td>牺牲买家维度灵活性</td></tr><tr><td>独立卖家库</td><td>数据同步到独立卖家库</td><td>链路复杂</td></tr></tbody></table><p>主流仍是 ES 异构索引，核心是接受秒级延迟并做对账。</p></li><li><p>【L4】订单系统有哪些失效场景？</p><p>ES 异构索引同步延迟时卖家看到旧数据。</p><p>大促建单洪峰下 DB 写入瓶颈，需提前压测 + MQ 削峰 + 预案降级。</p></li></ul></details><h4 id="🏭-实战场景-3" tabindex="-1"><a class="header-anchor" href="#🏭-实战场景-3"><span>🏭 实战场景</span></a></h4><details class="hint-container details"><summary>详情</summary><p><strong>电商平台大促订单系统</strong></p><p>场景：峰值 5 万 TPS 下单，订单日增 2000 万笔，买家查单占 90% 流量，卖家后台需按店铺/时间多维查询。</p><p>写路径：下单链路同步只做建单 + 预占库存，支付回调/通知/积分全部异步化，同步路径 RT 控制在 50ms 内。</p><p>存储：订单按买家 ID 分库分表（32 库 32 表起步，预留扩容），买家查单直查分片；binlog 经 Canal 同步到 ES 支撑卖家多维查询，容忍秒级延迟。</p><p>数据一致性：下单时快照商品名/价格/优惠，历史单不受商品变更影响。</p><p>归档：三个月以上订单归档历史库，在线库保持轻量。</p><p><strong>生产事故教训</strong>：曾有线上事故——订单未存快照直接关联商品表，商品改价后历史订单金额展示错乱，引发大量客诉。<strong>快照是订单系统的底线设计</strong>。</p></details><h4 id="⚠️-常见误区-3" tabindex="-1"><a class="header-anchor" href="#⚠️-常见误区-3"><span>⚠️ 常见误区</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li>❌ &quot;订单展示直接查商品表就行，不用存快照&quot; → 商品改价、下架会让历史订单金额与名称错乱，快照是底线设计。</li><li>❌ &quot;订单状态流转用应用层 if-else 控制就行&quot; → 并发与多入口（回调、定时任务、人工客服）下必然遗漏分支，必须带条件更新 + 合法迁移表，非法跳转直接拒绝并告警。</li><li>❌ &quot;用分布式事务保证订单、支付、库存强一致&quot; → 高并发下强一致的性能代价不可承受，业界主流是事件驱动 + 对账修复的最终一致性。</li></ul></details><h4 id="🔀-发散问题-7" tabindex="-1"><a class="header-anchor" href="#🔀-发散问题-7"><span>🔀 发散问题</span></a></h4><ul><li><p><strong>Q：订单状态机如何防止并发下非法流转？</strong></p><p>→ 更新语句带前置状态条件（<code>WHERE status = 前置态</code>）+ 影响行数判断，并发下只有一个变更能成功；状态机定义合法迁移表，非法跳转直接拒绝并告警，不依赖应用层 if-else 判断。</p></li><li><p><strong>Q：卖家维度查询除了 ES 还有什么方案？各自代价？</strong></p><p>→ 异构索引（ES/双库双写，延迟与一致性成本）、基因法分片（把卖家信息编入订单号，牺牲买家维度灵活性）、数据同步到独立卖家库（链路复杂）。主流是 ES 异构索引，核心是接受秒级延迟并做对账。</p></li><li><p><strong>Q：订单表多大需要分库分表？分片后如何支持多维查询？</strong></p><p>→ 单表超 5000 万行或单库写入超几千 TPS 时考虑；分片键选最高频查询维度（买家 ID），其余维度（卖家、手机号、时间范围）靠异构索引，不要在分库表上做全表扫。</p></li><li><p><strong>Q：订单幂等和支付回调幂等的共性是什么？</strong></p><p>→ 都是业务唯一键（下单幂等键、渠道交易号 + 支付单号）+ 唯一索引去重 + 状态机条件更新，见本文档「如何设计一个支付系统？」。</p></li></ul><h3 id="【困难】如何设计一个营销-优惠券系统-⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【困难】如何设计一个营销-优惠券系统-⭐⭐⭐⭐"><span>【困难】如何设计一个营销/优惠券系统？⭐⭐⭐⭐</span></a></h3><blockquote><p>🎯 目标等级：L3-L4 ｜ ⏱ 建议用时：20 min ｜ 🏷 标签：系统设计 / 营销</p></blockquote><h4 id="💎-关键结论-8" tabindex="-1"><a class="header-anchor" href="#💎-关键结论-8"><span>💎 关键结论</span></a></h4><p>优惠券本质是钱，设计核心是资产安全 + 高并发发放 + 规则正确：发放用 Redis Lua 预算前置扣减防超发，计算用分（long）+ 分摊算法保证实付不为负，状态变更全程记流水，每日对账保证账实相符。</p><h4 id="⚡-记忆卡片-8" tabindex="-1"><a class="header-anchor" href="#⚡-记忆卡片-8"><span>⚡ 记忆卡片</span></a></h4><ul><li><strong>口诀</strong>：发放先预扣、计算用分、分摊归尾、对账保平</li><li><strong>关键词</strong>：预算前置 ／ Redis Lua ／ 分（long）／ 分摊尾差 ／ 唯一索引幂等</li><li><strong>链路</strong>：创建模板 → Redis 预扣发放 → MQ 异步落库 → 下单锁定 → 支付核销 → 对账修复</li></ul><h4 id="📖-核心知识-8" tabindex="-1"><a class="header-anchor" href="#📖-核心知识-8"><span>📖 核心知识</span></a></h4><p>优惠券本质是<strong>钱</strong>，设计核心是<strong>资产安全 + 高并发发放 + 规则正确</strong>。</p><p><strong>1. 生命周期与状态机</strong></p><p>创建（活动模板）→ 发放 → 领取 → 锁定（下单占用）→ 使用/解锁（取消退回）→ 过期；每次状态变更写流水表，可审计对账。</p><p><strong>2. 高并发发放（防超发）</strong></p><ul><li>预算前置：活动总预算预扣到 Redis，Lua 脚本原子扣减（<code>if remain &gt; 0 then decr</code>），扣成功才写领取记录；</li><li>领取限流：单用户限领 N 张（Redis 计数）；风控前置（设备指纹/黑名单防羊毛党）；</li><li>异步落库：领取事件入 MQ 批量入库，Redis 与 DB 定时对账。</li></ul><p><strong>3. 优惠计算引擎（最容易出错）</strong></p><ul><li>优惠层级：商品级（直降）→ 订单级（满减）→ 支付级（立减），层级内互斥/叠加规则配置化；</li><li><strong>金额计算红线</strong>：用分（long）计算不用浮点；分摊算法保证&quot;各商品分摊之和 = 总优惠&quot;（尾差归到最后一件）；实付永不为负；</li><li>规则引擎化：互斥组、优先级、适用商品圈（类目/商品白名单）配置化，避免硬编码。</li></ul><p><strong>4. 资产安全</strong></p><ul><li>使用/退回必须幂等（订单 ID + 券 ID 唯一索引）；退款时券是否退回按业务规则配置；</li><li>每日对账：发放量 = 领取量 + 过期量 + 使用量，不平则告警人工介入。</li></ul><h4 id="🔬-扩展知识-8" tabindex="-1"><a class="header-anchor" href="#🔬-扩展知识-8"><span>🔬 扩展知识</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li><p>【L3】优惠券发放的性能上限怎么量化？</p><p>Redis Lua 预扣性能最高（单实例 8~10 万 QPS）但需与 DB 对账保一致性；纯 DB 领取（唯一索引防重）无一致性问题但峰值几千 QPS 就是瓶颈。</p><p>结论：大促领券必须预算前置到 Redis。</p></li><li><p>【L3】优惠规则引擎怎么设计？</p><p>互斥组、优先级、适用商品圈全部配置化而非硬编码。</p><p>规则变更走审批 + 灰度发布，避免运营误配置直接放大成资损。</p></li><li><p>【L4】优惠券系统有哪些失效场景？</p><p>Redis 预算与 DB 记录不一致时（如异步落库丢消息），需对账任务修正。</p><p>退款时券是否退还需按活动规则配置，默认不退易引客诉。</p></li><li><p>【L4】资损防线怎么设计？</p><p>&quot;实付不为负 + 优惠总额不超商品价&quot;必须是代码级硬校验，不能依赖运营配置正确。</p><p>配置只能决定优惠怎么组合，资金红线必须由代码兜底。</p></li></ul></details><h4 id="🏭-实战场景-4" tabindex="-1"><a class="header-anchor" href="#🏭-实战场景-4"><span>🏭 实战场景</span></a></h4><details class="hint-container details"><summary>详情</summary><p><strong>618 大促优惠券系统</strong></p><p>场景：平台券 1000 万张，开场 10 秒内领取峰值 8 万 QPS，单用户限领 3 张；券可与商品直降叠加但不可与店铺券叠加。</p><p>发放：券模板总预算 + 单用户限额全部前置 Redis，Lua 原子扣减（单实例 8~10 万 QPS 可扛，或拆两个分片）。</p><p>扣减成功发 MQ 异步落领取记录，同步接口 RT &lt; 20ms。</p><p>核销：下单时券状态置&quot;锁定&quot;（订单 ID 唯一索引防重），支付成功转&quot;已使用&quot;，取消退回。</p><p>计算与对账：优惠计算引擎硬校验实付 ≥ 0 + 互斥组规则，配置变更需审批；每日对账发放 = 领取 + 过期 + 使用，不平告警。</p><p><strong>生产事故教训</strong>：曾有线上事故——满减与店铺券叠加规则未配置互斥，两者叠加后实付为负，被羊毛党刷单数万元。<strong>&quot;实付不为负 + 优惠总额不超商品价&quot;必须是代码级硬校验</strong>。</p></details><h4 id="⚠️-常见误区-4" tabindex="-1"><a class="header-anchor" href="#⚠️-常见误区-4"><span>⚠️ 常见误区</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li>❌ &quot;优惠券金额用浮点数算，简单直观&quot; → 浮点精度丢失会导致分摊出现分级误差与账不平，必须以&quot;分&quot;为单位用 long 整型计算。</li><li>❌ &quot;互斥规则靠运营配置正确就行&quot; → 配置错误不可避免，实付不为负、优惠总额不超商品价必须做代码级硬校验兜底。</li><li>❌ &quot;Redis 扣预算成功就完事，不用和 DB 对账&quot; → 异步落库可能丢消息，预算与实际领取量会不一致，必须定时对账，不平告警人工介入。</li></ul></details><h4 id="🔀-发散问题-8" tabindex="-1"><a class="header-anchor" href="#🔀-发散问题-8"><span>🔀 发散问题</span></a></h4><ul><li><p><strong>Q：优惠分摊尾差问题怎么解？举例。</strong></p><p>→ 满 100 减 10，三件商品 33.33/33.33/33.34，按比例分摊每件减 3.33/3.33/3.34，尾差归最后一件；单件退款时按分摊后金额退，保证总账平衡。用分（long）计算避免浮点精度丢失。</p></li><li><p><strong>Q：领券峰值 10 万 QPS，如何防止单用户超领？</strong></p><p>→ Redis 原子计数 <code>INCR coupon:{id}:{userId}</code> 前置判断（超过限额拒绝），Lua 脚本内合并&quot;预算扣减 + 个人限额判断&quot;保证原子性；异步落库后用 DB 唯一索引（券 ID + 用户 ID）做最后防线。</p></li><li><p><strong>Q：优惠计算引擎如何保证规则变更不出错？</strong></p><p>→ 规则配置化 + 变更审批 + 发布前用历史订单回放验证（同样输入对比新旧引擎结果）；金额计算模块单测覆盖率要求 90%+，覆盖分摊、互斥、边界（实付为 0/优惠超商品价）用例。</p></li><li><p><strong>Q：优惠券防超发和秒杀扣库存有什么异同？</strong></p><p>→ 同为 Redis Lua 原子扣减 + 异步落库 + 对账兜底，优惠券多了单用户限领与互斥组校验；秒杀则多了漏斗式流量过滤，见本文档「如何设计一个秒杀系统？」。</p></li></ul><h3 id="【困难】如何设计一个支付系统-⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【困难】如何设计一个支付系统-⭐⭐⭐⭐"><span>【困难】如何设计一个支付系统？⭐⭐⭐⭐</span></a></h3><blockquote><p>🎯 目标等级：L3-L4 ｜ ⏱ 建议用时：20 min ｜ 🏷 标签：系统设计 / 支付</p></blockquote><h4 id="💎-关键结论-9" tabindex="-1"><a class="header-anchor" href="#💎-关键结论-9"><span>💎 关键结论</span></a></h4><p>支付系统第一原则是资金安全大于一切，宁可慢不可错。核心三模块：支付网关屏蔽渠道差异、支付单与业务订单解耦、账务复式记账；可靠性靠回调幂等 + 主动查单 + 日终对账三层兜底；金额全链路用分（long），余额只允许通过流水变更。</p><h4 id="⚡-记忆卡片-9" tabindex="-1"><a class="header-anchor" href="#⚡-记忆卡片-9"><span>⚡ 记忆卡片</span></a></h4><ul><li><strong>口诀</strong>：网关屏蔽、支付单解耦、复式记账、三层兜底</li><li><strong>关键词</strong>：支付网关 ／ 支付单 ／ 复式记账 ／ 回调幂等 ／ 对账</li><li><strong>链路</strong>：支付请求 → 网关路由渠道 → 支付单状态机 → 回调/查单确认 → 账务记账 → 对账核验</li></ul><h4 id="📖-核心知识-9" tabindex="-1"><a class="header-anchor" href="#📖-核心知识-9"><span>📖 核心知识</span></a></h4><p>支付系统的第一原则：<strong>资金安全大于一切，宁可慢不可错</strong>。</p><p><strong>1. 核心模块</strong></p><ul><li><strong>支付网关</strong>：统一对接微信/支付宝/银联等三方渠道，屏蔽差异（协议、回调格式、对账文件），支持通道路由与自动切换；</li><li><strong>支付单</strong>：与业务订单解耦（一笔订单可对应多笔支付单：重试、换渠道、拆单）；状态机：待支付 → 支付中 → 成功/失败/关闭；</li><li><strong>账务系统</strong>：复式记账（每笔交易借贷平衡），余额变更只允许通过账务流水，禁止直接改余额字段。</li></ul><p><strong>2. 关键设计</strong></p><ul><li><strong>回调幂等与状态驱动</strong>：三方回调可能重复/乱序到达，以渠道交易号 + 支付单号幂等去重；只允许&quot;待支付 → 成功&quot;单向迁移，终态后拒绝任何变更；</li><li><strong>主动查单兜底</strong>：回调丢失时定时任务主动调渠道查单接口补状态（注意频率限制）；</li><li><strong>对账体系</strong>（资损最后防线）：每日拉取渠道账单与本地流水逐笔核对，分差错账/长短款处理；实时对账监控金额突变；</li><li><strong>金额处理</strong>：全链路用分（long）；退款金额校验 ≤ 已付金额；手续费/分账规则单独建模；</li><li><strong>安全</strong>：签名验签、防重放（见《安全设计面试》『如何设计一个接口签名验证机制？』）；支付回调接口只信任服务端签名，不信任前端传参；密钥托管 KMS。</li></ul><p><strong>3. 性能量化</strong></p><p>大促支付峰值可达几十万 TPS，核心靠异步化（支付请求入 MQ 串行化处理同一用户）+ 渠道连接池复用 + 降级预案（非核心校验可关闭）。</p><h4 id="🔬-扩展知识-9" tabindex="-1"><a class="header-anchor" href="#🔬-扩展知识-9"><span>🔬 扩展知识</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li><p>【L4】主动查单的扫描频率怎么权衡？</p><p>主动查单是回调不可靠的必要兜底，但渠道查单接口有频率限制（通常每单每分钟几次），需控制扫描频率与优先级。</p><p>刚发起的订单高频查，久未完成的降频。</p></li><li><p>【L4】账务为什么坚持复式记账？</p><p>比单表余额更新复杂得多，但它是账务可审计、可对账的唯一途径。</p><p>绕过流水直接改余额，一旦并发出错将无法追溯，只能人工逐笔对账修复。</p></li><li><p>【L4】支付系统有哪些失效场景？</p><p>渠道侧回调与查单结果不一致时（如回调说成功、查单说处理中），以查单为准并进入差错账人工处理。</p><p>跨时区/跨渠道对账文件格式差异需适配层统一解析。</p></li><li><p>【L4】支付链路怎么保证变更安全与资损熔断？</p><p>支付核心链路发布必须可灰度、可监控、可回滚（变更三板斧）。</p><p>预置资损熔断开关——一键关闭某渠道支付并降级到剩余渠道。</p><p>实时对账监控到金额突变时自动熔断 + 告警，而不是等 T+1 对账或人工发现。</p></li></ul></details><h4 id="🏭-实战场景-5" tabindex="-1"><a class="header-anchor" href="#🏭-实战场景-5"><span>🏭 实战场景</span></a></h4><details class="hint-container details"><summary>详情</summary><p><strong>电商平台双 11 支付系统</strong></p><p>场景：支付峰值 10 万 TPS，对接微信/支付宝/银联三渠道，要求资损零容忍、渠道故障 1 分钟内可切换。</p><p>串行化：支付请求入 MQ 按用户维度串行化（同一用户顺序处理防并发双付）。</p><p>渠道路由：支付网关维护渠道健康度（成功率/RT 实时统计），渠道故障自动路由切换 + 人工一键切换开关。</p><p>一致性：回调幂等（渠道交易号 + 支付单号唯一索引）+ 主动查单兜底 + T+1 三方对账。</p><p>账务：复式记账保证借贷平衡，日切对账不平即告警。</p><p>容量：10 万 TPS 下应用层无状态水平扩容，瓶颈在渠道侧配额，需提前与渠道报备扩容。</p><p><strong>生产事故教训</strong>：曾有线上事故——直接 UPDATE 余额字段绕过账务流水，一次并发下余额错乱且无法追溯，最终人工逐笔对账修复。<strong>余额只允许通过流水变更</strong>。</p></details><h4 id="⚠️-常见误区-5" tabindex="-1"><a class="header-anchor" href="#⚠️-常见误区-5"><span>⚠️ 常见误区</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li>❌ &quot;支付回调可信，收到成功回调直接改单即可&quot; → 回调可能丢失、延迟甚至伪造，必须签名验签 + 幂等去重 + 主动查单 + 日终对账多层兜底。</li><li>❌ &quot;余额字段直接 UPDATE，比复式记账简单&quot; → 绕过流水的余额无法审计、无法对账，并发下错乱不可追溯；余额只允许通过账务流水变更。</li><li>❌ &quot;退款按用户申请金额直接退就行&quot; → 必须校验累计退款 ≤ 已付金额（应用层 + DB 带条件更新双层校验），并联动发票、已享优惠的业务规则。</li></ul></details><h4 id="🔀-发散问题-9" tabindex="-1"><a class="header-anchor" href="#🔀-发散问题-9"><span>🔀 发散问题</span></a></h4><ul><li><p><strong>Q：支付回调丢失或延迟的完整兜底链路？</strong></p><p>→ 三层：回调幂等去重 → 未终态支付单定时主动查单（优先级：刚发起的订单高频查，久未完成的降频）→ 日终对账拉渠道账单逐笔比对，长短款进差错账人工处理。</p></li><li><p><strong>Q：用户支付中重复点支付按钮怎么办？</strong></p><p>→ 同一订单已存在&quot;支付中&quot;支付单时，不新建支付单而是返回原支付单（唤起同一渠道交易），渠道侧也以商户单号幂等；超时未完成的支付单自动关闭后才能换渠道重发。</p></li><li><p><strong>Q：退款如何保证不超额？</strong></p><p>→ 退款单关联原支付单，累计退款额 ≤ 已付额在应用层 + DB 双层校验（<code>UPDATE ... WHERE 已退 + 本次 &lt;= 已付</code> 带条件更新）；部分退款需校验与已开发票、已享优惠的联动规则。</p></li><li><p><strong>Q：支付幂等和订单幂等的设计共性是什么？</strong></p><p>→ 都是业务唯一键 + 唯一索引 + 状态机单向迁移，终态后拒绝任何变更，见本文档「如何设计一个订单系统？」。</p></li></ul><h3 id="【困难】如何设计一个多租户-saas-系统-⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【困难】如何设计一个多租户-saas-系统-⭐⭐⭐⭐"><span>【困难】如何设计一个多租户 SaaS 系统？⭐⭐⭐⭐</span></a></h3><blockquote><p>🎯 目标等级：L3-L4 ｜ ⏱ 建议用时：20 min ｜ 🏷 标签：系统设计 / SaaS</p></blockquote><h4 id="💎-关键结论-10" tabindex="-1"><a class="header-anchor" href="#💎-关键结论-10"><span>💎 关键结论</span></a></h4><p>多租户 SaaS 的核心挑战是在共享基础设施上实现租户间的数据隔离、资源隔离与安全隔离。数据隔离有三种策略：共享表（tenant_id 字段，成本最低隔离最弱）、独立 Schema（同库不同 Schema，中等）、独立数据库（最强隔离最贵）；元数据驱动架构让一套代码通过配置差异化服务不同租户；安全隔离要做到认证鉴权租户化、资源配额防&quot;吵闹邻居&quot;。</p><h4 id="⚡-记忆卡片-10" tabindex="-1"><a class="header-anchor" href="#⚡-记忆卡片-10"><span>⚡ 记忆卡片</span></a></h4><ul><li><strong>口诀</strong>：共表独库分三级、元数据驱动一套皮、吵闹邻居要隔离、灰度按租户灰</li><li><strong>关键词</strong>：数据隔离三级 ／ 元数据驱动 ／ 吵闹邻居 ／ 租户配额 ／ 灰度发布</li><li><strong>链路</strong>：租户元数据 → 数据隔离策略选型 → 资源配额管控 → 安全隔离 → 灰度升级</li></ul><h4 id="📖-核心知识-10" tabindex="-1"><a class="header-anchor" href="#📖-核心知识-10"><span>📖 核心知识</span></a></h4><p><strong>1. 数据隔离策略</strong></p><table><thead><tr><th style="text-align:left;">策略</th><th style="text-align:left;">实现</th><th style="text-align:left;">优势</th><th style="text-align:left;">劣势</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>共享表</strong></td><td style="text-align:left;">所有租户数据存同一张表，通过 tenant_id 区分</td><td style="text-align:left;">成本最低、运维简单</td><td style="text-align:left;">隔离最弱，查询须带条件</td></tr><tr><td style="text-align:left;"><strong>独立 Schema</strong></td><td style="text-align:left;">同库不同 Schema，每租户一个 Schema</td><td style="text-align:left;">中等隔离、逻辑清晰</td><td style="text-align:left;">Schema 数量多时管理复杂</td></tr><tr><td style="text-align:left;"><strong>独立数据库</strong></td><td style="text-align:left;">每租户一个独立数据库</td><td style="text-align:left;">最强隔离、可独立备份</td><td style="text-align:left;">成本最高、运维复杂</td></tr></tbody></table><p>选型原则：小客户共享表、中客户独立 Schema、大客户独立数据库——按付费等级与合规需求分级。</p><p><strong>2. 元数据驱动架构</strong></p><ul><li><strong>核心</strong>：一套代码服务所有租户，差异化通过配置实现；</li><li><strong>租户元数据表</strong>：存储每个租户的版本号、功能开关、配额限制、自定义配置；</li><li><strong>业务代码</strong>：读取当前租户上下文（TenantContext）后决定逻辑分支或功能可见性；</li><li><strong>版本升级</strong>：通过功能开关按租户灰度——先内部租户、再白名单客户、最后全量。</li></ul><p><strong>3. 安全隔离</strong></p><ul><li><strong>认证隔离</strong>：每租户独立用户体系，支持自定义登录页 / SSO 对接 / LDAP 集成；</li><li><strong>授权隔离</strong>：租户管理员自定义角色与权限，不同租户的&quot;管理员&quot;权限范围不同；</li><li><strong>数据防泄漏</strong>：查询层强制注入 tenant_id 条件（框架层拦截器自动拼接），避免开发者遗漏导致跨租户数据泄露；</li><li><strong>资源配额</strong>：每租户设置存储上限、API 调用频次、并发连接数，防止&quot;吵闹邻居&quot;影响其他租户。</li></ul><p><strong>4. 资源隔离</strong></p><ul><li><strong>计算隔离</strong>：关键租户分配专属计算资源（独立线程池 / 容器），普通租户共享资源池；</li><li><strong>限流</strong>：按租户维度限流，某租户流量突增不影响其他租户；</li><li><strong>存储隔离</strong>：大租户的文件存独立 Bucket / 目录，按租户设置容量上限。</li></ul><h4 id="🔬-扩展知识-10" tabindex="-1"><a class="header-anchor" href="#🔬-扩展知识-10"><span>🔬 扩展知识</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li><p>【L3】租户上下文怎么在全链路传递？</p><p>请求入口解析 tenantId（从域名 / Header / Token 中提取），存入 ThreadLocal，全链路（Service → DAO → MQ）自动携带。</p><p>DAO 层通过 MyBatis 拦截器自动拼接 <code>WHERE tenant_id = ?</code>，避免开发者遗漏。</p></li><li><p>【L3】吵闹邻居（Noisy Neighbor）怎么防护？</p><p>按租户维度限流 + 资源配额（CPU / 内存 / 连接数 / 存储空间），关键租户分配专属资源池。</p><p>监控每租户的 P99 延迟与错误率，异常时自动降级该租户的非核心功能。</p></li><li><p>【L4】共享表与独立数据库方案怎么权衡，踩过什么坑？</p><table><thead><tr><th>隔离方案</th><th>运维成本</th><th>隔离强度</th><th>前提与适用场景</th></tr></thead><tbody><tr><td>共享表</td><td>运维最简单</td><td>隔离最弱</td><td>必须框架级强制注入租户条件</td></tr><tr><td>独立数据库</td><td>成本最高</td><td>隔离最强</td><td>金融 / 医疗等合规场景</td></tr></tbody></table><p>曾有线上事故：某报表查询漏写 <code>tenant_id</code> 条件，返回了全量租户数据——<strong>查询层必须框架级强制注入租户条件，不能依赖开发者手动添加</strong>。</p></li><li><p>【L4】500 租户、5 万 DAU、日增 10GB 的 SaaS 怎么分层？</p><table><thead><tr><th>租户分层</th><th>数量</th><th>方案</th></tr></thead><tbody><tr><td>小租户</td><td>400 个</td><td>共享表 + 共享资源池</td></tr><tr><td>中租户</td><td>80 个</td><td>独立 Schema + 独立限流配额</td></tr><tr><td>大客户</td><td>20 个</td><td>独立数据库 + 专属计算资源</td></tr></tbody></table><p>租户元数据存 Redis 缓存（TTL 5 分钟），变更通过 MQ 广播刷新。</p></li></ul></details><h4 id="🏭-实战场景-6" tabindex="-1"><a class="header-anchor" href="#🏭-实战场景-6"><span>🏭 实战场景</span></a></h4><details class="hint-container details"><summary>详情</summary><p><strong>B2B SaaS 平台多租户</strong></p><p>场景：500 家企业租户、5 万日活用户、日增数据 10GB，要求租户间数据零泄漏、大客户 P99 &lt; 200ms 不受小租户影响。</p><p>小租户（400 家）：共享数据库 + tenant_id 隔离，应用层 TenantContext 拦截器自动注入租户条件。</p><p>DB 层索引按 (tenant_id, business_key) 联合索引保证查询效率；中租户（80 家）独立 Schema，满足财务审计需求。</p><p>大客户（20 家）：独立数据库 + 专属资源池，满足合规要求。</p><p>资源管控：按租户维度令牌桶限流 + 存储配额，超限自动降级非核心功能。</p><p>灰度发布：新功能先对内部租户开放，再推白名单客户，最后全量。</p></details><h4 id="⚠️-常见误区-6" tabindex="-1"><a class="header-anchor" href="#⚠️-常见误区-6"><span>⚠️ 常见误区</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li>❌ &quot;SQL 都带了 tenant_id 就安全了&quot; → ORM 关联查询、原生 SQL、后台任务容易遗漏租户条件，必须在框架层（拦截器 / MyBatis 插件）自动注入，不能依赖开发者手动添加。</li><li>❌ &quot;所有租户共享资源，省钱&quot; → 大租户的批处理任务可能占满连接池导致小租户无法访问，必须按租户维度做限流和配额管理，必要时做计算资源隔离。</li><li>❌ &quot;多租户就是多套系统部署&quot; → 违背 SaaS 成本分摊的核心理念，应通过配置化和插件化满足定制需求，而非为每个租户独立部署。</li></ul></details><h4 id="🔀-发散问题-10" tabindex="-1"><a class="header-anchor" href="#🔀-发散问题-10"><span>🔀 发散问题</span></a></h4><ul><li><p><strong>Q：租户数据备份恢复怎么做？</strong></p><p>→ 共享表方案下备份通常是全库级别，恢复单租户需从全量备份中筛选（复杂且慢）；独立 Schema / 独立库方案可单独备份恢复，这也是大客户选择独立部署的原因之一。</p></li><li><p><strong>Q：如何评估一个租户是否该升级到独立部署？</strong></p><p>→ 看几个指标：数据量超过阈值（如 100GB）、QPS 超过阈值（如 1000）、有合规要求（如金融 / 医疗）、付费等级达到某级别——满足任一条件即触发升级评估。</p></li><li><p><strong>Q：多租户 SaaS 的计费系统有什么特殊之处？</strong></p><p>→ 每租户计费维度与单价不同（按用户数 / API 调用量 / 存储空间等），需在租户元数据中配置计费规则，用量数据按租户维度采集，计费任务按租户隔离执行避免互相影响。</p></li></ul><h3 id="【中等】如何设计一个-api-开放平台-⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【中等】如何设计一个-api-开放平台-⭐⭐⭐⭐"><span>【中等】如何设计一个 API 开放平台？⭐⭐⭐⭐</span></a></h3><blockquote><p>🎯 目标等级：L2-L3 ｜ ⏱ 建议用时：15 min ｜ 🏷 标签：系统设计 / 开放平台</p></blockquote><h4 id="💎-关键结论-11" tabindex="-1"><a class="header-anchor" href="#💎-关键结论-11"><span>💎 关键结论</span></a></h4><p>API 开放平台的核心是「安全 + 易用 + 可控」。身份认证用 OAuth 2.0 的应用级凭证（AppKey/AppSecret），流量管理靠 API 网关统一限流、熔断与鉴权，后端通过服务路由转发到业务服务；安全防护做请求签名、传输加密与防重放，开发者体验靠文档、SDK 与沙箱环境，商业变现靠调用计费与阶梯定价。</p><h4 id="⚡-记忆卡片-11" tabindex="-1"><a class="header-anchor" href="#⚡-记忆卡片-11"><span>⚡ 记忆卡片</span></a></h4><ul><li><strong>口诀</strong>：认证 OAuth、网关限流、签名防篡改、沙箱给开发</li><li><strong>关键词</strong>：OAuth 2.0 ／ API 网关 ／ 请求签名 ／ 开发者门户 ／ 调用计费</li><li><strong>链路</strong>：开发者注册 → 获取凭证 → 签名请求 → 网关鉴权限流 → 路由后端 → 计量计费</li></ul><h4 id="📖-核心知识-11" tabindex="-1"><a class="header-anchor" href="#📖-核心知识-11"><span>📖 核心知识</span></a></h4><p><strong>1. 身份认证与权限</strong></p><ul><li><strong>应用级凭证</strong>：每个接入方分配 AppKey + AppSecret，通过 OAuth 2.0 授权码模式（用户授权）或客户端凭证模式（服务端对服务端）获取 Access Token；</li><li><strong>Scope 权限</strong>：细粒度权限控制，如 <code>read:orders</code>、<code>write:products</code>，接入方只能调用已授权的 API；</li><li><strong>Token 管理</strong>：Access Token 短时效（2 小时），Refresh Token 长时效（30 天），支持主动吊销。</li></ul><p><strong>2. API 网关（核心组件）</strong></p><ul><li><strong>统一入口</strong>：所有外部请求经网关，内部服务不直接暴露；</li><li><strong>安全校验</strong>：签名验证（HMAC-SHA256）、HTTPS 强制、IP 白名单、参数校验防注入；</li><li><strong>流量管理</strong>：多维度限流（应用级 + 接口级 + 用户级）、熔断降级（后端故障时快速失败）；</li><li><strong>协议转换</strong>：外部 HTTP/REST → 内部 gRPC/Dubbo，屏蔽内部协议差异；</li><li><strong>日志审计</strong>：全量请求日志，支持追溯与对账。</li></ul><p><strong>3. 安全防护</strong></p><ul><li><strong>请求签名</strong>：AppSecret + 请求参数 + 时间戳拼接后 HMAC-SHA256 签名，服务端验签防篡改；</li><li><strong>防重放</strong>：请求带 timestamp + nonce，服务端校验时间窗口（±5 分钟）+ nonce 去重；</li><li><strong>传输加密</strong>：HTTPS 强制，敏感字段（如手机号）额外 RSA 加密；</li><li><strong>防注入</strong>：参数白名单校验、长度限制、特殊字符过滤。</li></ul><p><strong>4. 开发者体验</strong></p><ul><li><strong>开发者门户</strong>：API 文档（OpenAPI/Swagger 自动生成）、在线调试、SDK 下载；</li><li><strong>沙箱环境</strong>：独立测试环境 + 模拟数据，开发者无需对接真实业务即可调试；</li><li><strong>错误码体系</strong>：统一错误码规范（如 10001 = 签名错误、20001 = 库存不足），附排查建议；</li><li><strong>技术支持</strong>：工单系统 + 开发者社区 + 在线答疑。</li></ul><p><strong>5. 计量与计费</strong></p><ul><li><strong>计量</strong>：每次 API 调用记录（应用 + 接口 + 时间 + 状态码），异步写入计量库；</li><li><strong>计费</strong>：按调用次数阶梯定价（如 0~10 万次 0.01 元/次、10~100 万次 0.005 元/次）；</li><li><strong>对账</strong>：每日生成账单，支持开发者自助查询与申诉。</li></ul><h4 id="🔬-扩展知识-11" tabindex="-1"><a class="header-anchor" href="#🔬-扩展知识-11"><span>🔬 扩展知识</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li><p>【L3】OAuth 2.0 四种授权模式怎么选？</p><table><thead><tr><th>授权模式</th><th>适用</th><th>安全评价</th></tr></thead><tbody><tr><td>授权码模式</td><td>Web 应用</td><td>最安全</td></tr><tr><td>客户端凭证模式</td><td>服务端对服务端</td><td>—</td></tr><tr><td>密码模式</td><td>仅限第一方应用</td><td>不推荐第三方</td></tr><tr><td>隐式模式</td><td>已不推荐</td><td>Token 暴露在前端</td></tr></tbody></table></li><li><p>【L3】API 网关的限流算法有哪些，怎么组合？</p><table><thead><tr><th>限流算法</th><th>特点</th></tr></thead><tbody><tr><td>滑动窗口</td><td>比固定窗口避免边界突发</td></tr><tr><td>令牌桶</td><td>允许突发但限制总量</td></tr><tr><td>漏桶</td><td>强制平滑速率</td></tr></tbody></table><p>按场景组合使用，如应用级用令牌桶、接口级用漏桶。</p></li><li><p>【L4】API 版本怎么管理与下线？</p><p>URL 路径版本（/v1/、/v2/）最直观，Header 版本（Accept: application/vnd.xxx.v2+json）更优雅但调试不便。</p><p>旧版本设定废弃时间表（如 6 个月后下线），新版本上线时灰度发布（10% → 50% → 100%）。</p></li><li><p>【L4】开放平台的凭证泄露怎么应急？</p><p>曾有线上事故：某接入方 AppSecret 泄露后大量调用消耗配额，导致其他接入方被限流。</p><p><strong>AppSecret 泄露的应急预案必须提前演练</strong>，包括一键吊销 + 通知受影响方 + 自动补发新凭证。</p></li></ul></details><h4 id="🏭-实战场景-7" tabindex="-1"><a class="header-anchor" href="#🏭-实战场景-7"><span>🏭 实战场景</span></a></h4><details class="hint-container details"><summary>详情</summary><p><strong>企业开放平台</strong></p><p>场景：5000 个接入应用、日均 10 亿次 API 调用、峰值 QPS 10 万，要求 99.99% 可用、安全防护、精细化流量治理。</p><p>网关：API 网关独立集群部署（不与业务混部），Redis 集群做多维度限流计数（应用 + 接口组合粒度）。</p><p>认证与权限：OAuth 2.0 + JWT 做身份认证与细粒度权限（Scope 控制到接口级），请求签名用 HMAC-SHA256 防篡改。</p><p>计量：异步写 Kafka → Flink 实时聚合 → MySQL 落库。</p><p>开发者门户：提供 OpenAPI 文档 + 沙箱 + 自助排查工具。</p></details><h4 id="⚠️-常见误区-7" tabindex="-1"><a class="header-anchor" href="#⚠️-常见误区-7"><span>⚠️ 常见误区</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li>❌ &quot;网关做了限流就安全了&quot; → 限流只控制总量，不做应用级隔离时某应用的流量洪峰仍可能影响其他应用，必须应用级 + 接口级多维度限流。</li><li>❌ &quot;API 幂等性不重要，重试就行&quot; → 网络重试可能导致重复扣款或重复下单，写接口必须做幂等（requestId 去重），网关层可统一做请求去重。</li><li>❌ &quot;内部 API 直接暴露给外部&quot; → 内部 API 的数据结构和错误码不适合外部开发者，应在内部 API 前加一层 BFF（Backend for Frontend）做协议转换与数据裁剪。</li></ul></details><h4 id="🔀-发散问题-11" tabindex="-1"><a class="header-anchor" href="#🔀-发散问题-11"><span>🔀 发散问题</span></a></h4><ul><li><p><strong>Q：第三方应用密钥泄露如何应对？</strong></p><p>→ 应急预案：立即吊销该应用凭证 → 通知受影响用户 → 审计日志追溯影响范围 → 补发新密钥；长期方案：短期 Token + 自动轮换机制，减少密钥暴露窗口。</p></li><li><p><strong>Q：开放平台的计费系统如何保证不漏计？</strong></p><p>→ 每次 API 调用异步记录到 MQ → 定时任务消费 MQ 聚合后写 DB → 对账（MQ offset vs DB count）；短期用 Redis 计数器做实时限流，长期以 DB 计量为准做计费。</p></li><li><p><strong>Q：API 网关和内部 RPC 网关有什么区别？</strong></p><p>→ API 网关面向外部开发者，协议 HTTP/REST，重点在安全、鉴权、计费；RPC 网关面向内部微服务，协议 gRPC/Dubbo，重点在服务发现、负载均衡、链路追踪。</p></li></ul><h3 id="【困难】如何设计一个低代码平台-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【困难】如何设计一个低代码平台-⭐⭐⭐"><span>【困难】如何设计一个低代码平台？⭐⭐⭐</span></a></h3><blockquote><p>🎯 目标等级：L3-L4 ｜ ⏱ 建议用时：20 min ｜ 🏷 标签：系统设计 / 低代码</p></blockquote><h4 id="💎-关键结论-12" tabindex="-1"><a class="header-anchor" href="#💎-关键结论-12"><span>💎 关键结论</span></a></h4><p>低代码平台的核心是「组件化 + 可视化 + 可渲染」：物料层提供标准化组件协议，搭建层通过可视化编辑器拖拽生成 JSON Schema，渲染层解析 Schema 并渲染为可交互页面。关键挑战是组件生态的丰富度、渲染性能、以及逻辑编排的表达力。</p><h4 id="⚡-记忆卡片-12" tabindex="-1"><a class="header-anchor" href="#⚡-记忆卡片-12"><span>⚡ 记忆卡片</span></a></h4><ul><li><strong>口诀</strong>：物料标准化、搭建可视化、Schema 驱动、渲染多端</li><li><strong>关键词</strong>：组件协议 ／ JSON Schema ／ 可视化编辑器 ／ 渲染器 ／ 逻辑编排</li><li><strong>链路</strong>：组件注册 → 可视化拖拽 → Schema 输出 → 渲染执行 → 逻辑编排</li></ul><h4 id="📖-核心知识-12" tabindex="-1"><a class="header-anchor" href="#📖-核心知识-12"><span>📖 核心知识</span></a></h4><p><strong>1. 组件体系（物料层）</strong></p><ul><li><strong>组件协议</strong>：每个组件遵循统一协议，定义 props（输入属性）、events（输出事件）、methods（可调用方法）、slots（可插入位置）；</li><li><strong>基础组件库</strong>：按钮、输入框、表格、表单等原子组件；</li><li><strong>业务组件库</strong>：用户选择器、审批流组件、图表组件等封装业务逻辑的复合组件；</li><li><strong>物料市场</strong>：支持第三方组件接入，提供在线预览与一键安装。</li></ul><p><strong>2. 页面搭建（搭建层）</strong></p><ul><li><strong>可视化编辑器</strong>：拖拽组件到画布，配置属性面板，设置事件绑定；</li><li><strong>Schema 输出</strong>：编辑器将页面结构序列化为 JSON Schema（组件树 + 属性 + 事件 + 数据绑定）；</li><li><strong>撤销/重做</strong>：基于操作历史栈实现，每次操作记录 diff；</li><li><strong>协同编辑</strong>：多人同时编辑同一页面，需冲突解决（可参考实时协作系统的 CRDT/OT 方案）。</li></ul><p><strong>3. 页面渲染（渲染层）</strong></p><ul><li><strong>Schema 解析</strong>：渲染器递归遍历 Schema 树，实例化组件并注入属性与事件；</li><li><strong>数据绑定</strong>：支持声明式数据绑定（<code>{{dataSource.field}}</code>），数据变更自动触发组件重渲染；</li><li><strong>多端适配</strong>：同一 Schema 可被不同渲染器解析——Web 端用 Virtual DOM、小程序端用模板引擎、Native 端用原生视图。</li></ul><p><strong>4. 逻辑编排</strong></p><ul><li><strong>可视化流程编排</strong>：拖拽式流程图，支持条件分支、循环、异步调用、定时触发；</li><li><strong>表达式引擎</strong>：支持简单逻辑（如 <code>{{price * count}}</code>），复杂逻辑用自定义 DSL 或 JS 沙箱执行；</li><li><strong>内置函数库</strong>：常用操作（数据请求、表单校验、消息提示）封装为内置动作，用户直接调用。</li></ul><p><strong>5. 数据层</strong></p><ul><li><strong>数据模型定义</strong>：通过 Schema 定义数据结构，自动生成 CRUD 接口；</li><li><strong>数据源适配</strong>：支持对接 REST API、GraphQL、数据库等多种后端；</li><li><strong>表单与数据联动</strong>：声明式绑定 + 校验规则 + 联动逻辑（如&quot;省&quot;变更自动加载&quot;市&quot;列表）。</li></ul><p><strong>6. 扩展性设计</strong></p><ul><li><strong>自定义组件</strong>：用户可开发私有组件接入平台；</li><li><strong>自定义渲染器</strong>：支持新终端（如 IoT 设备屏幕）接入；</li><li><strong>插件机制</strong>：编译时插件（修改 Schema）+ 运行时插件（拦截渲染过程）；</li><li><strong>OpenAPI</strong>：平台的组件管理、应用发布等能力开放给外部系统。</li></ul><h4 id="🔬-扩展知识-12" tabindex="-1"><a class="header-anchor" href="#🔬-扩展知识-12"><span>🔬 扩展知识</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li><p>【L3】低代码的 Schema 设计有哪些关键决策？</p><table><thead><tr><th>设计维度</th><th>做法</th></tr></thead><tbody><tr><td>组件嵌套</td><td>用树形结构（parent-children）</td></tr><tr><td>数据绑定</td><td>用表达式引用（<code>{{model.field}}</code>）</td></tr><tr><td>事件绑定</td><td>用动作列表（onClick → [setVariable, requestAPI]）</td></tr><tr><td>Schema 版本化</td><td>用 v1/v2 保证旧页面在新版平台仍可渲染</td></tr></tbody></table></li><li><p>【L3】Schema 节点过多时怎么优化渲染性能？</p><p>Schema 节点过多（&gt;1000）时渲染卡顿，优化手段包括：</p><table><thead><tr><th>优化手段</th><th>做法</th></tr></thead><tbody><tr><td>虚拟列表</td><td>只渲染可见区域</td></tr><tr><td>懒加载</td><td>滚动到视口时才渲染</td></tr><tr><td>增量更新</td><td>只更新变更的子树而非整页重渲染</td></tr></tbody></table></li><li><p>【L4】低代码平台的核心竞争力在哪里？</p><p>核心竞争力不在编辑器（编辑器是交互层，可替换），而在组件生态（物料丰富度决定平台价值）和渲染性能（大页面不卡顿是用户体验底线）。</p><p>曾有线上案例：某低代码平台组件库只有 30 个基础组件，用户不得不大量使用&quot;自定义代码块&quot;，低代码退化为 ProCode——<strong>物料丰富度是低代码平台的生命线</strong>。</p></li></ul></details><h4 id="🏭-实战场景-8" tabindex="-1"><a class="header-anchor" href="#🏭-实战场景-8"><span>🏭 实战场景</span></a></h4><details class="hint-container details"><summary>详情</summary><p><strong>企业级低代码平台</strong></p><p>场景：支撑 2000 个内部应用、300 个组件、50 个租户，日活用户 3 万。</p><p>组件协议：标准化（props/events/methods/slots 五要素），团队基于协议开发组件并接入物料市场。</p><p>渲染层：采用 Virtual DOM + 增量更新，长列表用虚拟滚动（只渲染可视区域 20 条），大数据表格用虚拟列渲染。</p><p>逻辑编排：用可视化流程编辑器 + 自定义表达式引擎（沙箱执行 JS 子集，限制执行时间防死循环）。</p></details><h4 id="⚠️-常见误区-8" tabindex="-1"><a class="header-anchor" href="#⚠️-常见误区-8"><span>⚠️ 常见误区</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li>❌ &quot;低代码平台不需要开发者&quot; → 低代码降低的是重复劳动的门槛，复杂业务逻辑仍需专业开发者编排；定位是&quot;让开发者聚焦业务而非重复造轮子&quot;。</li><li>❌ &quot;低代码可以替代所有开发&quot; → 低代码适合中后台、表单、流程等标准化场景，复杂交互（如游戏、设计工具）不适合，过度追求&quot;万能&quot;会导致平台臃肿且体验差。</li><li>❌ &quot;编辑器最重要，做好编辑器就行&quot; → 编辑器只是交互入口，组件协议才是生态基础——协议决定了组件能否被编辑器识别、渲染器渲染、逻辑引擎调用，协议设计不好，生态无法扩展。</li></ul></details><h4 id="🔀-发散问题-12" tabindex="-1"><a class="header-anchor" href="#🔀-发散问题-12"><span>🔀 发散问题</span></a></h4><ul><li><p><strong>Q：低代码和 ProCode 的边界怎么划分？</strong></p><p>→ 一般规律：表单 / 表格 / 流程等 CRUD 场景用低代码，复杂交互 / 定制化需求用 ProCode；边界不是固定的，随着组件能力增强，低代码能覆盖的场景会扩大。</p></li><li><p><strong>Q：组件协议应该包含哪些核心字段？</strong></p><p>→ 最少五个：name（组件标识）、props（输入属性定义）、events（输出事件定义）、methods（可调用方法）、slots（可插入位置）；props 定义&quot;组件长什么样&quot;，events 定义&quot;组件能通知什么&quot;，methods 定义&quot;外部能控制什么&quot;。</p></li><li><p><strong>Q：低代码平台的渲染性能瓶颈在哪？</strong></p><p>→ 主要在 Schema 树的递归渲染——节点数超过千级时容易卡顿，优化手段：虚拟列表（只渲染可见区域）、增量渲染（只更新变更子树）、Web Worker（将 Schema 解析放到 Worker 线程避免阻塞主线程）。</p></li></ul><h3 id="【困难】如何设计一个实时协作系统-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【困难】如何设计一个实时协作系统-⭐⭐⭐"><span>【困难】如何设计一个实时协作系统？⭐⭐⭐</span></a></h3><blockquote><p>🎯 目标等级：L3-L4 ｜ ⏱ 建议用时：20 min ｜ 🏷 标签：系统设计 / 协作</p></blockquote><h4 id="💎-关键结论-13" tabindex="-1"><a class="header-anchor" href="#💎-关键结论-13"><span>💎 关键结论</span></a></h4><p>实时协作系统的核心是「最终一致性 + 低延迟同步」：用 CRDT 或 OT 算法解决多端并发编辑的冲突，WebSocket 长连接实现毫秒级消息广播，在线状态（presence）管理用户的&quot;谁在线/光标在哪&quot;信息，冲突解决依赖向量时钟或 Lamport 时间戳定序。</p><h4 id="⚡-记忆卡片-13" tabindex="-1"><a class="header-anchor" href="#⚡-记忆卡片-13"><span>⚡ 记忆卡片</span></a></h4><ul><li><strong>口诀</strong>：CRDT 合、WebSocket 推、presence 显、向量钟定序</li><li><strong>关键词</strong>：CRDT/OT ／ WebSocket ／ presence ／ 向量时钟 ／ 最终一致性</li><li><strong>链路</strong>：编辑操作 → CRDT/OT 转换 → WebSocket 广播 → 客户端合并渲染 → 离线缓存上线同步</li></ul><h4 id="📖-核心知识-13" tabindex="-1"><a class="header-anchor" href="#📖-核心知识-13"><span>📖 核心知识</span></a></h4><p><strong>1. 协同算法选型</strong></p><table><thead><tr><th style="text-align:left;">算法</th><th style="text-align:left;">原理</th><th style="text-align:left;">优势</th><th style="text-align:left;">劣势</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>OT</strong></td><td style="text-align:left;">操作变换，中心服务器协调操作顺序</td><td style="text-align:left;">成熟（Google Docs 采用）</td><td style="text-align:left;">依赖中心服务器，实现复杂</td></tr><tr><td style="text-align:left;"><strong>CRDT</strong></td><td style="text-align:left;">无冲突复制数据类型，每个节点独立运算合并</td><td style="text-align:left;">适合 P2P / 离线优先</td><td style="text-align:left;">实现复杂，元数据开销大</td></tr></tbody></table><ul><li><strong>OT（Operational Transformation）</strong>：适合有中心服务器的场景，中心服务器做操作变换保证一致性；</li><li><strong>CRDT（Conflict-free Replicated Data Type）</strong>：适合 P2P 或弱网场景，每个节点可独立运算合并，无需中心仲裁。</li></ul><p><strong>2. 实时通信</strong></p><ul><li><strong>WebSocket 长连接</strong>：全双工通信，毫秒级延迟；</li><li><strong>消息协议</strong>：自定义二进制协议（如 Protocol Buffers）减少带宽，或 JSON（开发效率高）；</li><li><strong>消息类型</strong>：编辑操作（insert/delete/update）、光标移动、presence 更新、ACK 确认。</li></ul><p><strong>3. 在线状态（Presence）</strong></p><ul><li><strong>在线列表</strong>：显示当前文档/房间的所有在线用户；</li><li><strong>光标同步</strong>：实时显示其他用户的光标位置与选区；</li><li><strong>实现</strong>：每个客户端定时上报心跳 + 光标位置，服务端广播给所有协作者；用户离开时服务端通知移除。</li></ul><p><strong>4. 冲突解决</strong></p><ul><li><strong>向量时钟</strong>：每个节点维护版本号数组，用于判断事件的因果关系（先于/后于/并发）；</li><li><strong>Lamport 时间戳</strong>：逻辑时钟，保证全序但可能误判并发关系；</li><li><strong>最后写入胜出（LWW）</strong>：简单但可能丢数据，适合低冲突场景。</li></ul><p><strong>5. 离线支持</strong></p><ul><li><strong>本地缓存</strong>：离线时操作存 IndexedDB / LocalStorage；</li><li><strong>上线同步</strong>：重连后按时间顺序回放本地操作，CRDT 自动合并无冲突，有冲突需用户手动解决；</li><li><strong>冲突提示</strong>：合并后如存在语义冲突（如两人同时修改同一段文字），高亮提示用户选择。</li></ul><h4 id="🔬-扩展知识-13" tabindex="-1"><a class="header-anchor" href="#🔬-扩展知识-13"><span>🔬 扩展知识</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li><p>【L3】OT vs CRDT 怎么选型？</p><table><thead><tr><th>维度</th><th>OT</th><th>CRDT</th></tr></thead><tbody><tr><td>适用架构</td><td>有中心服务器且需要强控制（如审计日志）</td><td>P2P / 弱网 / 离线优先</td></tr><tr><td>典型产品</td><td>Google Docs</td><td>Figma</td></tr><tr><td>实现复杂度</td><td>—</td><td>CRDT 更高，但去中心化特性适合现代分布式架构</td></tr></tbody></table></li><li><p>【L3】实时协作的 WebSocket 网关要设计哪些能力？</p><table><thead><tr><th>网关职责</th><th>做法</th></tr></thead><tbody><tr><td>连接管理</td><td>维护 userId → 连接映射</td></tr><tr><td>消息路由</td><td>找到目标用户所在网关节点</td></tr><tr><td>跨节点广播</td><td>Redis Pub/Sub 或 Kafka</td></tr></tbody></table><p>水平扩容时网关节点无状态，连接映射存 Redis。</p></li><li><p>【L4】向量时钟 vs Lamport 时间戳差在哪？</p><p>向量时钟能准确判断&quot;并发&quot;关系（两个事件互不知晓对方）。</p><p>Lamport 时间戳只能给出全序，但可能将并发的两个事件排成先后。</p><p>代价是向量时钟的空间开销随节点数线性增长。</p></li></ul></details><h4 id="🏭-实战场景-9" tabindex="-1"><a class="header-anchor" href="#🏭-实战场景-9"><span>🏭 实战场景</span></a></h4><details class="hint-container details"><summary>详情</summary><p><strong>在线文档协同编辑器</strong></p><p>场景：支持 100 人同时编辑同一文档，同步延迟 &lt; 1 秒，要求 99.9% 可用、支持离线编辑。</p><p>协同算法：用 CRDT（如 Yjs 库的 YXmlText 类型），每个客户端独立运算合并无需中心仲裁。</p><p>连接与离线：WebSocket 长连接 + 心跳保活（30 秒一次），断线时本地缓存操作（IndexedDB），上线后批量同步。</p><p>presence 服务：用 Redis Hash 存储每个文档的在线用户列表与光标位置，Pub/Sub 广播变更。</p></details><h4 id="⚠️-常见误区-9" tabindex="-1"><a class="header-anchor" href="#⚠️-常见误区-9"><span>⚠️ 常见误区</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li>❌ &quot;OT 比 CRDT 成熟，一定选 OT&quot; → 选择取决于部署模式：有中心服务器且需强控制选 OT，P2P 或弱网选 CRDT；CRDT 在 Figma、Yjs 等产品中已验证可用。</li><li>❌ &quot;实时协作必须强一致&quot; → 大多数协作场景最终一致即可，强一致意味着每次操作都要等网络往返，体验极差；应优先保证本地操作即时反馈（乐观更新），再异步同步。</li><li>❌ &quot;WebSocket 断线重连后全量同步最简单&quot; → 文档大时全量同步带宽消耗巨大，应记录版本号（或操作日志位点），断线重连后只同步增量（从上次版本号到最新）。</li></ul></details><h4 id="🔀-发散问题-13" tabindex="-1"><a class="header-anchor" href="#🔀-发散问题-13"><span>🔀 发散问题</span></a></h4><ul><li><p><strong>Q：Google Docs 和 Figma 的协作方案有什么区别？</strong></p><p>→ Google Docs 用 OT 算法，需要中心服务器协调操作顺序；Figma 用 CRDT 变体，每个客户端可独立运算合并，离线支持更好。</p></li><li><p><strong>Q：大规模协作（如千人同时在线）怎么优化？</strong></p><p>→ 分区广播（只广播给关注同一区域的用户，如文档的同一章节）+ 操作合并（短时间内的多个操作合并为一条消息减少广播量）。</p></li><li><p><strong>Q：离线编辑冲突如何处理？</strong></p><p>→ CRDT 能自动合并无冲突的操作（如两人编辑不同段落），有语义冲突时（如两人同时修改同一段文字）需用户手动选择保留哪个版本，提供版本对比 UI 辅助决策。</p></li></ul><h2 id="架构模式" tabindex="-1"><a class="header-anchor" href="#架构模式"><span>架构模式</span></a></h2><h3 id="【困难】如何设计一个高并发系统-⭐⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【困难】如何设计一个高并发系统-⭐⭐⭐⭐⭐"><span>【困难】如何设计一个高并发系统？⭐⭐⭐⭐⭐</span></a></h3><blockquote><p>🎯 目标等级：L3-L4 ｜ ⏱ 建议用时：20 min ｜ 🏷 标签：架构设计 / 高并发</p></blockquote><h4 id="💎-关键结论-14" tabindex="-1"><a class="header-anchor" href="#💎-关键结论-14"><span>💎 关键结论</span></a></h4><p>高并发设计没有银弹，核心方法论是：尽量减少请求、让请求更快、把压力摆平，可归纳为六字诀——缓、异、池、拆、预、水。最有效的优化是把请求消灭在入口（缓存与前端拦截），其次异步化摆平峰值；选型前必须先逐层量化每一层承受的压力，再选手段。</p><h4 id="⚡-记忆卡片-14" tabindex="-1"><a class="header-anchor" href="#⚡-记忆卡片-14"><span>⚡ 记忆卡片</span></a></h4><ul><li><strong>口诀</strong>：能挡就挡（缓存），能异步就异步，能拆就拆，先量化再选型</li><li><strong>关键词</strong>：多级缓存 ／ MQ 削峰 ／ 池化 ／ 无状态拆分 ／ 预计算 ／ 水平扩容</li><li><strong>链路</strong>：减少请求 → 异步摆平 → 池化复用 → 拆分散压 → 预计算 → 扩容兜底</li></ul><h4 id="📖-核心知识-14" tabindex="-1"><a class="header-anchor" href="#📖-核心知识-14"><span>📖 核心知识</span></a></h4><p>高并发设计可归纳为六字诀：<strong>缓、异、池、拆、预、水</strong>。</p><p><strong>一、减少请求（最有效的优化）</strong></p><ul><li><strong>前端拦截</strong>：静态化 + CDN、按钮防重、本地缓存；秒杀场景 99% 请求应在到达后端前被拦截。</li><li><strong>多级缓存</strong>：浏览器缓存 → CDN → 网关缓存 → 本地缓存（Caffeine）→ 分布式缓存（Redis），层层挡住读流量。</li><li><strong>读写分离</strong>：主库写、从库读；读多写少的系统收益最大。</li></ul><p><strong>二、异步化（把同步变异步，把峰值摆平）</strong></p><ul><li>MQ 削峰填谷：下单、发短信、发积分等非核心链路异步化。</li><li>同步调用链能并行就并行（CompletableFuture 聚合多下游）。</li></ul><p><strong>三、池化与复用</strong>：线程池、连接池、对象池，避免频繁创建销毁的资源开销。</p><p><strong>四、拆分（水平扩展的前提）</strong></p><ul><li>服务拆分：无状态化才能随意水平扩容；有状态部分外置（Session、计数器进 Redis）。</li><li>数据拆分：分库分表打散写入热点；热点数据单独隔离部署。</li></ul><p><strong>五、预计算/预加载</strong>：提前算好结果（如大促前预热缓存、提前生成静态页），把实时计算变为查表。</p><p><strong>六、水平扩容 + 容量水位</strong>：无状态服务按需扩容，配合限流兜底；日常水位控制在 50%~60%，给突发留余量。</p><p><strong>量化示例</strong>：某读接口 10w QPS，多级缓存命中率 95% 后仅 5k 打到 DB；写接口 1w QPS 经 MQ 削峰后按 2k/s 平滑消费——<strong>先算清楚每一层要承受多少压力，再选手段</strong>。</p><h4 id="🔬-扩展知识-14" tabindex="-1"><a class="header-anchor" href="#🔬-扩展知识-14"><span>🔬 扩展知识</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li><p>【L3】系统做到什么程度算&quot;扛住了&quot;？</p><p>要给出三层数字：</p><table><thead><tr><th>层次</th><th>口径</th></tr></thead><tbody><tr><td>容量</td><td>单机 1500 QPS × 20 台 × 60% 水位 ≈ 1.8 万安全 QPS</td></tr><tr><td>实测</td><td>全链路压测拐点值</td></tr><tr><td>余量</td><td>目标流量的 2 倍以上</td></tr></tbody></table><p>汇报口径是&quot;可承载 X 倍峰值，瓶颈在 Y，扩容弹性为 Z&quot;。</p></li><li><p>【L3】优化手段中哪类收益最大、哪类最容易翻车？</p><p>收益最大的是缓存与前端拦截（把请求消灭在入口，量级削减）。</p><p>最易翻车的是异步化与分库分表——异步引入一致性/积压问题，分库分表引入跨片查询与扩容困难，都要有配套兜底方案才敢上。</p></li><li><p>【L4】无状态化改造的具体做法是什么？</p><p>Session/登录态、计数器、本地文件、定时任务锁都要外置到 Redis/调度平台；本地缓存可保留但只做加速副本。</p><p>判断标准：任意实例被随机杀掉，用户请求不受影响，即为无状态。</p></li><li><p>【L4】全链路压测与容量评估怎么做成常态化运营？</p><p>生产环境压测依赖流量染色（压测流量打标）+ 影子库/影子表（压测写落影子存储，不污染生产数据）+ 第三方通道 Mock。</p><p>压测数据需可构造、可清理。</p><p>容量评估应做成持续运营体系——容量水位看板、变更前容量验证卡点、扩缩容联动，而不是大促前的一次性压测。</p></li></ul></details><h4 id="🏭-实战场景-10" tabindex="-1"><a class="header-anchor" href="#🏭-实战场景-10"><span>🏭 实战场景</span></a></h4><details class="hint-container details"><summary>详情</summary><p><strong>大促活动页高并发场景</strong></p><p>场景：大促活动页峰值 20 万 QPS 查询活动商品信息，DB 单实例极限 5000 QPS，现有预算只允许加 10 台应用服务器。</p><p>方案：静态页 + CDN 挡掉约 95% 读流量，回源约 1 万 QPS。</p><p>应用层本地缓存（Caffeine，TTL 1~5s）再挡 80%，打到 Redis 约 2000 QPS，Redis 单实例 8~10 万 QPS 完全可扛。</p><p>DB 仅在缓存故障兜底，前置限流 3000 QPS 保护。</p><p>容量核算：10 台服务器单机只需承担约 2 万 QPS 的纯内存计算 + 缓存访问，4C8G 即可。核心是<strong>逐层量化漏斗</strong>，而不是堆机器。</p><p>失效场景与踩坑：缓存命中率一旦从 95% 跌到 50%（如缓存集群故障），DB 流量翻倍以上，未做限流兜底会直接雪崩。</p><p>缓存是最脆弱的依赖，必须有降级预案。</p><p>MQ 削峰的前提是消费端能消化，消费速度 &lt; 生产速度时积压会反噬（磁盘写满、重投风暴）。</p><p>某次大促因未对缓存击穿做兜底，单热点 key 过期瞬间数万 QPS 穿透到 DB，接口全面超时——<strong>热点数据必须永不过期或互斥重建</strong>。</p></details><h4 id="⚠️-常见误区-10" tabindex="-1"><a class="header-anchor" href="#⚠️-常见误区-10"><span>⚠️ 常见误区</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li>❌ &quot;高并发就是加机器&quot; → 不先做缓存/异步减少请求量，堆机器只是线性成本换线性容量，瓶颈层（如 DB）依然先挂。</li><li>❌ &quot;上了缓存就万事大吉&quot; → 缓存命中率骤降时流量全打到 DB，必须配限流与降级预案。</li><li>❌ &quot;MQ 削峰能解决一切写压力&quot; → 消费速度跟不上生产速度时积压反噬（磁盘写满、重投风暴），削峰的前提是消费端能消化。</li></ul></details><h4 id="🔀-发散问题-14" tabindex="-1"><a class="header-anchor" href="#🔀-发散问题-14"><span>🔀 发散问题</span></a></h4><ul><li><p><strong>Q：限流、熔断、降级在高并发体系中如何配合？</strong></p><p>→ 限流挡超量、熔断防故障扩散、降级保核心，阈值必须来自压测容量，见「如何实现流量控制」。</p></li><li><p><strong>Q：高并发系统的容量如何评估与验证？</strong></p><p>→ 从业务指标倒推峰值 QPS，全链路压测找拐点，见「如何做系统容量评估与压测」。</p></li><li><p><strong>Q：大促后服务重启会不会引发重连洪峰？</strong></p><p>→ 客户端退避抖动 + 服务端渐进放量协同解决，见「服务重启时，如何避免客户端重连引发的流量洪峰」。</p></li></ul><h3 id="【困难】如何设计异地多活-容灾架构-⭐⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【困难】如何设计异地多活-容灾架构-⭐⭐⭐⭐⭐"><span>【困难】如何设计异地多活/容灾架构？⭐⭐⭐⭐⭐</span></a></h3><blockquote><p>🎯 目标等级：L3-L4 ｜ ⏱ 建议用时：20 min ｜ 🏷 标签：架构设计 / 容灾多活</p></blockquote><h4 id="💎-关键结论-15" tabindex="-1"><a class="header-anchor" href="#💎-关键结论-15"><span>💎 关键结论</span></a></h4><p>容灾按等级演进：冷备 → 同城双活 → 异地多活，核心指标是 RTO（多久恢复）与 RPO（丢多少数据）。异地多活的根本难点是跨城同步延迟，解法是单元化——按用户维度把流量和数据封闭在单元内闭环，只异步同步少量全局数据。实践上先同城双活、再异地冷备、最后按核心链路单元化；没演练过的容灾等于没有容灾。</p><h4 id="⚡-记忆卡片-15" tabindex="-1"><a class="header-anchor" href="#⚡-记忆卡片-15"><span>⚡ 记忆卡片</span></a></h4><ul><li><strong>口诀</strong>：单元闭环写，全局单点写，容量 N/(N-1)，演练才作数</li><li><strong>关键词</strong>：RTO ／ RPO ／ 单元化 ／ GSLB ／ 切流演练</li><li><strong>链路</strong>：冷备 → 同城双活 → 异地多活 → 单元化闭环 → 定期切流演练</li></ul><h4 id="📖-核心知识-15" tabindex="-1"><a class="header-anchor" href="#📖-核心知识-15"><span>📖 核心知识</span></a></h4><p><strong>容灾等级与指标</strong></p><table><thead><tr><th style="text-align:left;">等级</th><th style="text-align:left;">形态</th><th style="text-align:left;">RTO/RPO</th></tr></thead><tbody><tr><td style="text-align:left;">冷备</td><td style="text-align:left;">数据备份，手动恢复</td><td style="text-align:left;">小时级</td></tr><tr><td style="text-align:left;">同城双活</td><td style="text-align:left;">两机房同时服务</td><td style="text-align:left;">分钟级，RPO ≈ 0</td></tr><tr><td style="text-align:left;">异地多活</td><td style="text-align:left;">多城市机房同时服务</td><td style="text-align:left;">秒级切换，RPO 极小</td></tr></tbody></table><ul><li><strong>RTO</strong>（恢复时间目标）：故障后多久恢复服务；<strong>RPO</strong>（恢复点目标）：允许丢多少数据。</li></ul><p><strong>同城双活</strong>：两机房网络延迟低（&lt;2ms），数据库一主一从或双主（MGR），应用无状态双部署，负载均衡按机房分流；单机房故障秒级切流。</p><p><strong>异地多活的核心难点与设计</strong></p><ol><li><strong>数据同步延迟</strong>：跨城延迟 30ms+，异步同步必然存在延迟窗口。解法：<strong>单元化（Set 化）</strong>——按用户维度（如 userId 取模）把流量和数据封闭在单个单元内闭环，单元间只异步同步少量全局数据，从根本上避免跨单元写冲突。</li><li><strong>流量调度</strong>：DNS/GSLB + 网关层按路由规则（userId hash）把请求导入对应单元；切流能力需分钟级生效。</li><li><strong>全局数据一致性</strong>：配置、商品等全局数据用&quot;单点写 + 多单元读&quot;或同步双写。</li><li><strong>容量规划</strong>：N 个单元需承担 (N/(N-1)) 倍容量（挂一个后其余能承接全量），通常按 N+1 冗余。</li></ol><p><strong>实践建议</strong>：不要一步到位——先同城双活，再异地冷备，最后按核心链路逐步单元化；<strong>定期切流演练</strong>，没演练过的容灾等于没有容灾。</p><p><strong>方案权衡</strong>：异地多活的成本是指数级上升的（多套机房、多套数据同步链路、单元化改造人力），绝大多数业务做到同城双活 + 异地冷备即可；只有金融级合规或超大流量平台才值得全量单元化。<strong>代价</strong>：写路径变长（跨单元同步 30ms+）、容量冗余 N/(N-1)、全局数据改造复杂。</p><h4 id="🔬-扩展知识-15" tabindex="-1"><a class="header-anchor" href="#🔬-扩展知识-15"><span>🔬 扩展知识</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li><p>【L3】单元化改造中，哪些数据最难闭环？</p><p>全局共享且高频写的数据最难（如全局库存、号段、配置）。常见解法：</p><table><thead><tr><th>数据</th><th>闭环做法</th></tr></thead><tbody><tr><td>库存</td><td>按单元预分配，各单元持有份额，单元间余量调拨</td></tr><tr><td>号段</td><td>按单元分配不重叠区间</td></tr><tr><td>配置</td><td>走单点写多单元读</td></tr></tbody></table></li><li><p>【L4】RPO=0 和 RTO=0 能否同时做到？</p><table><thead><tr><th>指标</th><th>可行性</th><th>代价</th></tr></thead><tbody><tr><td>RPO=0</td><td>同城双活 + 同步复制可接近 RPO=0</td><td>同步复制引入写延迟（跨机房 1~2ms RTT），一机房网络抖动会拖慢所有写</td></tr><tr><td>RTO=0</td><td>需流量自动调度 + 无状态秒级接管</td><td>常驻双倍容量</td></tr></tbody></table><p>异地物理距离决定 RPO 无法为 0，只能靠业务补偿。</p></li><li><p>【L4】如何验证容灾方案真的有效？</p><p>定期真实切流演练（生产环境小流量→全量）、混沌工程注入机房级故障、演练恢复时长并量化 RTO/RPO 实际值与目标差距。</p><p>演练结果纳入容量与预案持续改进。</p></li><li><p>【L4】切流期间的重试风暴怎么防放大？</p><p>机房故障切流期间，全链路的超时重试会把流量放大数倍（重试风暴）。</p><p>需预算化重试（限制重试流量占比）+ 指数退避带抖动 + 熔断快速失败，否则切流本身引发二次雪崩。</p><p>机房级故障的工程路径普遍要求&quot;1 分钟发现、5 分钟定位、10 分钟恢复&quot;（1-5-10，业界通用口径）。</p><p>这依赖全链路监控 + 预案自动化，而非人工救火。</p></li></ul></details><h4 id="🏭-实战场景-11" tabindex="-1"><a class="header-anchor" href="#🏭-实战场景-11"><span>🏭 实战场景</span></a></h4><details class="hint-container details"><summary>详情</summary><p><strong>支付平台两地三中心容灾</strong></p><p>场景：支付平台日交易 500 万笔，监管要求 RTO ≤ 5 分钟、RPO ≤ 30 秒，预算只够两地三中心（同城两机房 + 异地一机房）。</p><p>方案：同城两机房做双活（&lt;2ms 延迟支持同步/半同步复制，RPO≈0），承担日常全部流量。</p><p>异地机房异步复制（延迟窗口通常秒级，满足 RPO≤30s）+ 定期全量备份，平时只读引流少量验证流量。</p><p>切换：同城单机房故障由负载均衡秒级切流（RTO&lt;1 分钟）。</p><p>同城双毁时切异地，容忍最多 30 秒未同步交易，配合<strong>日终渠道对账 + 人工补单</strong>兜底资损。</p><p>预算约束下的核心权衡：把钱花在同城高可用（高频故障），异地保底（低频灾难）。</p><p>失效场景与踩坑：DNS 切流依赖 TTL（分钟级），故障初期仍有流量打到坏机房，需网关层秒级切流配合。</p><p>跨城异步同步必然有延迟窗口，故障切换瞬间可能丢最近几秒数据（RPO&gt;0）——资金类数据需业务层对账补偿。</p><p>曾有大厂演练时切流成功，但<strong>依赖的第三方服务不支持多活</strong>，切流后核心链路调第三方全失败——容灾方案必须覆盖所有外部依赖。</p></details><h4 id="⚠️-常见误区-11" tabindex="-1"><a class="header-anchor" href="#⚠️-常见误区-11"><span>⚠️ 常见误区</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li>❌ &quot;做了异地多活就不会丢数据&quot; → 跨城异步同步必有延迟窗口，切换瞬间 RPO&gt;0，资金类必须业务层对账补偿。</li><li>❌ &quot;切流演练过一次就行&quot; → 依赖会持续变化（新增第三方、新服务），必须常态化演练，没演练过的预案等于没有。</li><li>❌ &quot;容灾方案覆盖自己的系统就够了&quot; → 外部依赖不支持多活时，切流后核心链路照样全挂，方案必须覆盖所有依赖方。</li></ul></details><h4 id="🔀-发散问题-15" tabindex="-1"><a class="header-anchor" href="#🔀-发散问题-15"><span>🔀 发散问题</span></a></h4><ul><li><p><strong>Q：机房级容灾与高可用设计是什么关系？</strong></p><p>→ 多活是高可用&quot;冗余消单点&quot;在机房级的延伸，见「如何设计一个高可用系统」。</p></li><li><p><strong>Q：多活下的全局唯一 ID 怎么分配？</strong></p><p>→ 号段按单元分配不重叠区间，机器 ID 自动化分配，见「如何设计一个分布式 ID 发号器」。</p></li></ul><h2 id="数据密集" tabindex="-1"><a class="header-anchor" href="#数据密集"><span>数据密集</span></a></h2><h3 id="【困难】如何设计一个搜索引擎-⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【困难】如何设计一个搜索引擎-⭐⭐⭐⭐"><span>【困难】如何设计一个搜索引擎？⭐⭐⭐⭐</span></a></h3><blockquote><p>🎯 目标等级：L3-L4 ｜ ⏱ 建议用时：25 min ｜ 🏷 标签：搜索 / 架构</p></blockquote><h4 id="💎-关键结论-16" tabindex="-1"><a class="header-anchor" href="#💎-关键结论-16"><span>💎 关键结论</span></a></h4><p>搜索引擎三大核心：<strong>索引构建</strong>（分词→倒排索引）、<strong>查询处理</strong>（分词→布尔/向量检索→打分排序）、<strong>结果展示</strong>（摘要高亮+分页）。大规模系统需分布式索引（Shard）+ 副本（Replica）；Google 的三驾马车是 GFS/MapReduce/Bigtable。</p><h4 id="⚡-记忆卡片-16" tabindex="-1"><a class="header-anchor" href="#⚡-记忆卡片-16"><span>⚡ 记忆卡片</span></a></h4><ul><li><strong>口诀</strong>：分词建倒排，查询走打分，分布靠分片</li><li><strong>关键词</strong>：倒排索引 ／ TF-IDF ／ BM25 ／ Shard+Replica</li><li><strong>链路</strong>：文档 → 分词 → 构建倒排索引 → 查询分词 → 检索+打分 → 排序+摘要 → 返回</li></ul><h4 id="📖-核心知识-16" tabindex="-1"><a class="header-anchor" href="#📖-核心知识-16"><span>📖 核心知识</span></a></h4><ol><li><strong>倒排索引</strong>：Term → PostingList(docId, tf, positions)；支持布尔查询（AND/OR/NOT 取交集/并集/差集）。</li><li><strong>相关性打分</strong>：TF-IDF（词频-逆文档频率）→ BM25（TF 饱和+文档长度归一化）；现代搜索引擎用 Learning-to-Rank。</li><li><strong>分布式架构</strong>：索引按 Shard 水平分片；每个 Shard 有 Replica 保证高可用；Coordinator 节点聚合各 Shard 结果。</li><li><strong>近实时搜索</strong>：NRT（Near Real Time）——写入先入内存 Segment，refresh（默认 1s）后变为可搜索的 Segment。</li></ol><h4 id="🔬-扩展知识-16" tabindex="-1"><a class="header-anchor" href="#🔬-扩展知识-16"><span>🔬 扩展知识</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li><p>【L3】什么情况下选 Elasticsearch，什么情况下自建？</p><p>通用业务搜索直接选 Elasticsearch（倒排索引 + 分布式分片副本 + 生态齐全）。</p><p>自建只在有特殊打分逻辑、超大规模成本敏感等强定制需求时才考虑。</p><p>自建的代价是重造分片路由、副本容错、refresh/merge 机制，维护成本极高。</p><p>&quot;为什么选 ES、什么情况下换掉&quot;是本题的决策论证层。</p></li><li><p>【L4】搜索的写入与查询调优怎么权衡？</p><table><thead><tr><th>调优项</th><th>收益</th><th>代价</th></tr></thead><tbody><tr><td>refresh_interval 调大（如 30s）</td><td>提升写吞吐</td><td>牺牲可见时效</td></tr><tr><td>Segment 合并（merge）</td><td>—</td><td>与查询争抢 IO，写高峰需限流</td></tr><tr><td>副本数</td><td>换读容量</td><td>放大写与存储成本</td></tr></tbody></table></li><li><p>【L4】搜索相关性打分是怎么演进的？</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>BM25 静态打分            // 1. 字面匹配</span></span>
<span class="line"><span>LTR                    // 2. 用点击日志做训练样本</span></span>
<span class="line"><span>语义向量召回               // 3. 双塔 + ANN，补足字面匹配盲区</span></span>
<span class="line"><span>混合检索                  // 4. 字面 + 向量，当前主流形态</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li></ul></details><h4 id="⚠️-常见误区-12" tabindex="-1"><a class="header-anchor" href="#⚠️-常见误区-12"><span>⚠️ 常见误区</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li>❌ &quot;LIKE &#39;%关键词%&#39; 就能当搜索用&quot; → 前置通配符无法利用 B+ 树索引，全表扫描且没有分词与相关性打分，数据量稍大必须换倒排索引。</li><li>❌ &quot;ES 开箱即用不需要容量规划&quot; → 分片数需按数据量与写入吞吐预先规划，单分片过大恢复/迁移慢，分片过碎集群元数据压力大，两头都是坑。</li></ul></details><hr><h3 id="【困难】如何设计一个自动补全系统-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【困难】如何设计一个自动补全系统-⭐⭐⭐"><span>【困难】如何设计一个自动补全系统？⭐⭐⭐</span></a></h3><blockquote><p>🎯 目标等级：L3 ｜ ⏱ 建议用时：20 min ｜ 🏷 标签：搜索 / 自动补全</p></blockquote><h4 id="💎-关键结论-17" tabindex="-1"><a class="header-anchor" href="#💎-关键结论-17"><span>💎 关键结论</span></a></h4><p>自动补全的核心数据结构是 <strong>Trie（前缀树）+ 优先队列</strong>。用户每输入一个字符，沿 Trie 下探找到匹配前缀的所有候选，按热度/权重排序取 Top-K。大规模系统用分布式 Trie 或 FST（Finite State Transducer）压缩内存。</p><h4 id="⚡-记忆卡片-17" tabindex="-1"><a class="header-anchor" href="#⚡-记忆卡片-17"><span>⚡ 记忆卡片</span></a></h4><ul><li><strong>口诀</strong>：前缀树找候选，热度排 Top-K</li><li><strong>关键词</strong>：Trie ／ FST ／ Top-K ／ 实时索引</li><li><strong>链路</strong>：用户输入 → Trie 前缀匹配 → 候选按热度排序 → 返回 Top-K → 用户继续输入重复</li></ul><h4 id="📖-核心知识-17" tabindex="-1"><a class="header-anchor" href="#📖-核心知识-17"><span>📖 核心知识</span></a></h4><ol><li><strong>Trie 结构</strong>：每个节点是一个字符；从根到叶的路径是一个完整词；每个节点维护 children 映射和 isEnd 标记。</li><li><strong>Top-K 优化</strong>：每个 Trie 节点缓存以该前缀开头的 Top-10 热词；更新时用优先队列维护。</li><li><strong>容错处理</strong>：拼写纠错（编辑距离 ≤2 的候选）；同义词扩展（&quot;手机&quot; → &quot;移动电话&quot;）。</li><li><strong>工程挑战</strong>：内存优化——FST 比 Trie 省 10 倍内存；实时更新——增量构建 + 热备切换。</li></ol><h4 id="🔬-扩展知识-17" tabindex="-1"><a class="header-anchor" href="#🔬-扩展知识-17"><span>🔬 扩展知识</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li><p>【L3】FST vs Trie 怎么权衡？</p><p>FST 前后缀共享大幅压缩内存（Lucene term 字典即用 FST）。</p><p>代价是查询需解压更慢、只能整体构建不能单条增量。</p><p>所以实时热词需&quot;FST 全量 + 内存增量层&quot;双结构合并查询。</p></li><li><p>【L4】热词热度怎么实时更新？</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>行为日志（曝光/点击）        // 1. 采集</span></span>
<span class="line"><span>流式计算按窗口聚合词热度      // 2. 窗口聚合</span></span>
<span class="line"><span>周期性重建或增量合并索引      // 3. 索引更新</span></span>
<span class="line"><span>双 buffer 热切换           // 4. 对外无感切换</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>热度需带时间衰减，否则旧热词长期霸榜。</p></li></ul></details><hr><h3 id="【困难】如何设计一个推荐系统-⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【困难】如何设计一个推荐系统-⭐⭐⭐⭐"><span>【困难】如何设计一个推荐系统？⭐⭐⭐⭐</span></a></h3><blockquote><p>🎯 目标等级：L4 ｜ ⏱ 建议用时：25 min ｜ 🏷 标签：推荐 / 架构</p></blockquote><h4 id="💎-关键结论-18" tabindex="-1"><a class="header-anchor" href="#💎-关键结论-18"><span>💎 关键结论</span></a></h4><p>推荐系统经典三段式：<strong>召回</strong>（候选集从百万→千）→ <strong>排序</strong>（千→百，精排模型）→ <strong>重排</strong>（百→展示，业务规则+多样性）。召回用协同过滤/向量检索；排序用 GBDT/LR/DeepFM；重排去重、打散、插入广告。</p><h4 id="⚡-记忆卡片-18" tabindex="-1"><a class="header-anchor" href="#⚡-记忆卡片-18"><span>⚡ 记忆卡片</span></a></h4><ul><li><strong>口诀</strong>：召回粗筛千选一，精排打分百留十，重排打散保多样</li><li><strong>关键词</strong>：召回 ／ 排序 ／ 重排 ／ 协同过滤 ／ DeepFM</li><li><strong>链路</strong>：用户行为 → 召回（CF/向量） → 粗排 → 精排模型打分 → 重排（多样性+业务规则） → 展示</li></ul><h4 id="📖-核心知识-18" tabindex="-1"><a class="header-anchor" href="#📖-核心知识-18"><span>📖 核心知识</span></a></h4><ol><li><strong>召回策略</strong>：① 基于用户 CF（找相似用户喜欢的）；② 基于物品 CF（找相似物品）；③ 向量召回（双塔模型+ANN 检索）；④ 标签/热度召回。</li><li><strong>排序模型演进</strong>：LR → FM → DeepFM → DIN（注意力机制）→ 多目标优化（MMOE）。</li><li><strong>冷启动</strong>：用户冷启动——用注册信息/设备信息/热门兜底；物品冷启动——Bandit 探索（UCB/Thompson Sampling）。</li><li><strong>评估指标</strong>：离线 AUC/NDCG；在线 CTR/CVR/人均观看时长。</li></ol><h4 id="🔬-扩展知识-18" tabindex="-1"><a class="header-anchor" href="#🔬-扩展知识-18"><span>🔬 扩展知识</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li><p>【L3】推荐分层漏斗的本质是什么？</p><p>本质是延迟预算分配：召回在几十 ms 内从百万粗筛到千，精排单候选打分成本最高所以只处理百级候选。</p><p>每加一层都是用算力换候选规模，层数与候选量按端到端延迟预算反推。</p></li><li><p>【L4】在线与离线特征一致性怎么保证？</p><p>训练特征（离线批处理）与在线打分特征（实时拉取）口径漂移会导致&quot;离线 AUC 涨、线上不涨&quot;。</p><p>需特征快照回流——把线上打分实际使用的特征记录下来作为训练样本。</p></li><li><p>【L4】推荐系统需要哪些工程兜底与实验体系？</p><p>推荐服务超时必须降级为热门榜/运营榜，不能阻塞页面。</p><p>A/B 分流与指标归因是排序策略迭代的前提，没有实验平台的推荐系统无法证明改动有效。</p></li></ul></details><h4 id="⚠️-常见误区-13" tabindex="-1"><a class="header-anchor" href="#⚠️-常见误区-13"><span>⚠️ 常见误区</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li>❌ &quot;推荐系统 = 训练一个大模型&quot; → 工程上是召回/排序/重排流水线 + 特征体系 + 实验平台，模型只是其中一环，数据链路与降级设计同样决定成败。</li><li>❌ &quot;单目标把 CTR 做到最高就行&quot; → 会催生标题党与信息茧房，需多目标融合（时长/互动/多样性）并在重排层打散。</li></ul></details><hr><h3 id="【困难】如何设计一个搜索结果排序系统-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【困难】如何设计一个搜索结果排序系统-⭐⭐⭐"><span>【困难】如何设计一个搜索结果排序系统？⭐⭐⭐</span></a></h3><blockquote><p>🎯 目标等级：L4 ｜ ⏱ 建议用时：20 min ｜ 🏷 标签：搜索 / Ranking</p></blockquote><h4 id="💎-关键结论-19" tabindex="-1"><a class="header-anchor" href="#💎-关键结论-19"><span>💎 关键结论</span></a></h4><p>搜索排序从规则到学习的演进：<strong>BM25 文本相关性</strong> → <strong>特征工程+LR</strong> → <strong>GBDT+LR</strong> → <strong>Deep Learning（DIN/DIEN）</strong>。核心是 Learning-to-Rank（LTR）：Pointwise（回归/分类）、Pairwise（排序对比较）、Listwise（直接优化 NDCG）。</p><h4 id="⚡-记忆卡片-19" tabindex="-1"><a class="header-anchor" href="#⚡-记忆卡片-19"><span>⚡ 记忆卡片</span></a></h4><ul><li><strong>口诀</strong>：相关是基础，特征定高低，学习排顺序</li><li><strong>关键词</strong>：BM25 ／ LTR ／ Pointwise/Pairwise/Listwise ／ 多目标融合</li><li><strong>链路</strong>：查询+文档 → 提取特征 → 模型打分 → 多目标融合（相关+新鲜+权威） → 排序输出</li></ul><h4 id="📖-核心知识-19" tabindex="-1"><a class="header-anchor" href="#📖-核心知识-19"><span>📖 核心知识</span></a></h4><ol><li><strong>特征体系</strong>：查询相关性特征（BM25/语义向量相似度）；文档质量特征（PageRank/点击率）；用户特征（历史偏好/地域）。</li><li><strong>LTR 三范式</strong>：Pointwise（每个文档独立打分）；Pairwise（文档对偏序，如 RankSVM）；Listwise（整个列表最优，如 LambdaMART）。</li><li><strong>多目标融合</strong>：相关性 × 时效性 × 权威性 × 商业价值；用线性加权或 Pareto 最优。</li><li><strong>在线学习</strong>：实时反馈（点击/跳过）更新模型；Bandit 算法平衡探索与利用。</li></ol><h4 id="🔬-扩展知识-19" tabindex="-1"><a class="header-anchor" href="#🔬-扩展知识-19"><span>🔬 扩展知识</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li><p>【L3】排序系统的工程落地（Java 后端侧）要注意什么？</p><p>特征服务实时拉取须在延迟预算内完成，模型推理服务与业务解耦独立部署，打分结果可缓存复用。</p><p>LambdaMART（基于 GBDT 的 Listwise 方法）是深度模型之前的主流选择，中小场景至今仍广泛使用。</p></li><li><p>【L4】多目标融合的权重怎么定？</p><p>权重演进路径：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>人工拍权重          // 1. 起步</span></span>
<span class="line"><span>基于线上 A/B 实验调优  // 2. 用实验数据校准</span></span>
<span class="line"><span>自动调参            // 3. 交给搜索/优化算法</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>融合公式变更必须灰度放量，直接全量会让指标波动无法归因。</p></li></ul></details><hr><h3 id="【困难】如何实现分布式搜索-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【困难】如何实现分布式搜索-⭐⭐⭐"><span>【困难】如何实现分布式搜索？⭐⭐⭐</span></a></h3><blockquote><p>🎯 目标等级：L3 ｜ ⏱ 建议用时：20 min ｜ 🏷 标签：搜索 / 分布式</p></blockquote><h4 id="💎-关键结论-20" tabindex="-1"><a class="header-anchor" href="#💎-关键结论-20"><span>💎 关键结论</span></a></h4><p>分布式搜索的核心是<strong>索引分片 + 查询聚合</strong>。索引按 Shard 水平切分（按 docId hash 或路由字段）；查询时 Coordinator 广播到所有 Shard，各 Shard 本地排序后返回 Top-N，Coordinator 全局归并排序。</p><h4 id="⚡-记忆卡片-20" tabindex="-1"><a class="header-anchor" href="#⚡-记忆卡片-20"><span>⚡ 记忆卡片</span></a></h4><ul><li><strong>口诀</strong>：索引分片存，查询广播聚，归并排全局</li><li><strong>关键词</strong>：Shard ／ Coordinator ／ Scatter-Gather ／ 深分页代价</li><li><strong>链路</strong>：查询 → Coordinator 广播到 N 个 Shard → 各 Shard 本地排序返回 Top-N → Coordinator 全局归并</li></ul><h4 id="📖-核心知识-20" tabindex="-1"><a class="header-anchor" href="#📖-核心知识-20"><span>📖 核心知识</span></a></h4><ol><li><strong>分片策略</strong>：按 docId hash 均匀分布；或按路由字段（如 tenant_id）将相关数据集中到同一 Shard。</li><li><strong>查询两阶段</strong>：Query Phase（各 Shard 返回 docId+score）→ Fetch Phase（Coordinator 按 docId 去对应 Shard 取完整文档）。</li><li><strong>深分页问题</strong>：from=10000 size=10 需每个 Shard 返回 10010 条，Coordinator 归并 10010×Shard 数；解决方案：search_after + 滚动。</li><li><strong>一致性</strong>：写入后 refresh（默认 1s）才可见；强一致场景用 GET by ID（实时获取，走 translog）。</li></ol><h4 id="🔬-扩展知识-20" tabindex="-1"><a class="header-anchor" href="#🔬-扩展知识-20"><span>🔬 扩展知识</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li><p>【L3】分布式搜索的分片数怎么规划？</p><p>单分片建议控制在几十 GB 量级（ES 官方经验区间约 10~50GB）。</p><p>分片过大故障恢复与迁移慢，过碎则集群状态元数据压力大。</p><p>总分片数 = 数据量 / 单分片容量，并预留增长。</p></li><li><p>【L4】分片与副本的可用性、成本怎么权衡？</p><p>分片故障会让整体查询降级，副本保高可用但写放大与存储翻倍。</p><p>多机房部署时考虑查询路由亲和（同机房副本优先），避免跨机房 Scatter-Gather 放大延迟。</p></li></ul></details><hr><h3 id="【困难】如何设计一个实时热搜-趋势系统-⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【困难】如何设计一个实时热搜-趋势系统-⭐⭐⭐"><span>【困难】如何设计一个实时热搜/趋势系统？⭐⭐⭐</span></a></h3><blockquote><p>🎯 目标等级：L3 ｜ ⏱ 建议用时：20 min ｜ 🏷 标签：搜索 / 实时</p></blockquote><h4 id="💎-关键结论-21" tabindex="-1"><a class="header-anchor" href="#💎-关键结论-21"><span>💎 关键结论</span></a></h4><p>实时热搜 = <strong>流式聚合 + 时间衰减 + 去噪</strong>。数据流：用户行为 → Kafka → Flink/Spark Streaming 按时间窗口聚合关键词频次 → 时间衰减打分（新词加分、老词降权）→ 去重去噪（同义词合并、低质过滤）→ 输出 Top-50 榜单。</p><h4 id="⚡-记忆卡片-21" tabindex="-1"><a class="header-anchor" href="#⚡-记忆卡片-21"><span>⚡ 记忆卡片</span></a></h4><ul><li><strong>口诀</strong>：行为入流聚合快，时间衰减去噪快</li><li><strong>关键词</strong>：流式聚合 ／ 时间窗口 ／ 衰减函数 ／ 去噪</li><li><strong>链路</strong>：用户行为 → Kafka → 流引擎窗口聚合 → 衰减打分 → 去重去噪 → Top-50 榜单</li></ul><h4 id="📖-核心知识-21" tabindex="-1"><a class="header-anchor" href="#📖-核心知识-21"><span>📖 核心知识</span></a></h4><ol><li><strong>聚合策略</strong>：滑动时间窗口（最近 1h/6h/24h）；多粒度聚合（分钟级实时+小时级趋势）。</li><li><strong>趋势算法</strong>：① 简单频次排名；② 时间衰减（score = count × decay_factor^age）；③ Twitter 算法（对比当前频次与历史基线的偏差）。</li><li><strong>去噪</strong>：停用词过滤；同义词合并（&quot;iPhone16&quot;=&quot;苹果16&quot;）；防刷（单用户/单 IP 频次上限）。</li><li><strong>工程架构</strong>：Kafka（缓冲）→ Flink（窗口聚合）→ Redis（存 Top-N 榜单）→ CDN 缓存（前端读取）。</li></ol><h4 id="🔬-扩展知识-21" tabindex="-1"><a class="header-anchor" href="#🔬-扩展知识-21"><span>🔬 扩展知识</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li><p>【L3】热度衰减与趋势算法怎么选？</p><p>指数衰减（count × decay^age）实现简单、榜单平滑。</p><p>对比历史基线偏差（Twitter 式 Trends）能识别&quot;突然变热&quot;的新词。</p><p>两者可加权组合，兼顾持续热度与突发热点。</p></li><li><p>【L4】热搜榜单怎么做防刷对抗？</p><p>榜单是公开舆论入口，被刷代价高。</p><p>手段：单用户/单设备频次上限、新注册账号降权、异常突增词先进人工复核再上榜。</p><p>词库与阈值需随对抗持续迭代。</p></li></ul></details><hr><h3 id="【困难】如何设计一个内容安全审核系统-⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【困难】如何设计一个内容安全审核系统-⭐⭐⭐⭐"><span>【困难】如何设计一个内容安全审核系统？⭐⭐⭐⭐</span></a></h3><blockquote><p>🎯 目标等级：L3-L4 ｜ ⏱ 建议用时：20 min ｜ 🏷 标签：搜索 / 安全</p></blockquote><h4 id="💎-关键结论-22" tabindex="-1"><a class="header-anchor" href="#💎-关键结论-22"><span>💎 关键结论</span></a></h4><p>内容审核是<strong>多层过滤管线</strong>：① 规则层（关键词/正则/黑名单，毫秒级）→ ② 模型层（文本分类/图像识别/NLP 模型，百毫秒级）→ ③ 人工层（模型不确定的转人工复核）。核心指标：召回率 &gt; 准确率（宁可误杀不可漏放）。</p><h4 id="⚡-记忆卡片-22" tabindex="-1"><a class="header-anchor" href="#⚡-记忆卡片-22"><span>⚡ 记忆卡片</span></a></h4><ul><li><strong>口诀</strong>：规则快筛模型判，不确定的人工看</li><li><strong>关键词</strong>：多层管线 ／ 规则+模型+人工 ／ 召回优先 ／ Aho-Corasick</li><li><strong>链路</strong>：内容输入 → 规则快筛 → 模型打分 → 置信度高直接放行/拦截 → 中间地带转人工</li></ul><h4 id="📖-核心知识-22" tabindex="-1"><a class="header-anchor" href="#📖-核心知识-22"><span>📖 核心知识</span></a></h4><ol><li><strong>文本审核</strong>：关键词匹配用 Aho-Corasick 多模式匹配（一次扫描匹配所有关键词）；变体对抗（谐音/拆字/拼音）用模糊匹配+模型。</li><li><strong>图像审核</strong>：CNN 分类器（涉黄/暴恐/广告）；OCR 提取图中文字再过文本审核；以图搜图（感知 hash）比对已知违规图。</li><li><strong>性能要求</strong>：同步审核 &lt;200ms（影响用户体验）；大批量异步审核（如历史数据回扫）。</li><li><strong>运营闭环</strong>：误判申诉 → 标注回流 → 模型迭代；关键词库热更新；审核策略 A/B 测试。</li></ol><h4 id="🔬-扩展知识-22" tabindex="-1"><a class="header-anchor" href="#🔬-扩展知识-22"><span>🔬 扩展知识</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li><p>【L3】先审后发 vs 先发后审怎么选？</p><table><thead><tr><th>时机策略</th><th>优点</th><th>代价</th></tr></thead><tbody><tr><td>先审后发</td><td>安全</td><td>有审核延迟</td></tr><tr><td>先发后审</td><td>时效强</td><td>违规内容短暂可见</td></tr></tbody></table><p>UGC 高时效场景多用&quot;先发后审 + 高风险类目先审后发&quot;的混合策略，按内容风险分级配置。</p></li><li><p>【L4】置信度分层怎么运营？</p><p>高置信拦截 / 高置信放行全自动，只有中间地带转人工。</p><p>人工复核区间的宽窄直接决定成本与漏放率的平衡，阈值需按申诉率与抽检漏放率动态校准。</p></li><li><p>【L4】审核怎么应对违规内容的对抗性演进？</p><p>变体（谐音/拆字/emoji 插入）迭代极快，关键词库热更新 + 对抗样本回流再训练是常态。</p><p>审核系统是持续运营的对抗体系，不是一次性交付的管线。</p></li></ul></details><h3 id="【困难】如何设计一个消息推送系统-千万级用户-⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【困难】如何设计一个消息推送系统-千万级用户-⭐⭐⭐⭐"><span>【困难】如何设计一个消息推送系统（千万级用户）？⭐⭐⭐⭐</span></a></h3><blockquote><p>🎯 目标等级：L3 ｜ ⏱ 建议用时：15 min ｜ 🏷 标签：场景设计 / 系统设计</p></blockquote><h4 id="💎-关键结论-23" tabindex="-1"><a class="header-anchor" href="#💎-关键结论-23"><span>💎 关键结论</span></a></h4><p>整体链路：<strong>任务调度 → 人群圈选 → 消息生产 → MQ 削峰 → 分通道发送集群 → 状态回传与统计</strong>。关键四件事：分片并行提吞吐、幂等键防重发、限流与重试保通道、频控免打扰保合规。千万用户 5 分钟触达 ≈ 3.3 万条/秒，必须批量接口 + 多通道并行。</p><h4 id="⚡-记忆卡片-23" tabindex="-1"><a class="header-anchor" href="#⚡-记忆卡片-23"><span>⚡ 记忆卡片</span></a></h4><ul><li><strong>口诀</strong>：圈人分片投 MQ，分道限速批量发，幂等防重退避重，频控免扰状态收</li><li><strong>关键词</strong>：人群圈选 ／ MQ 削峰 ／ 幂等键 ／ 限流重试 ／ 频控</li><li><strong>链路</strong>：任务调度 → 圈选分片 → MQ 削峰 → 分通道发送 → 回执统计</li></ul><h4 id="📖-核心知识-23" tabindex="-1"><a class="header-anchor" href="#📖-核心知识-23"><span>📖 核心知识</span></a></h4><p><strong>需求拆解</strong>：千万级用户在指定时间收到 Push/短信/站内信，分钟级触达，不重不漏。</p><p><strong>整体架构</strong>：任务调度 → 人群圈选 → 消息生产 → MQ 削峰 → 发送集群（分通道）→ 状态回传与统计。</p><p><strong>核心设计</strong></p><ul><li><strong>人群圈选</strong>：定时任务扫描（索引 expire_date）或用圈人服务（标签/位图）产出目标用户列表，分片存储（如按 userId hash 切 1000 片）。</li><li><strong>削峰与并发</strong>：目标用户 ID 分片写入 MQ，发送集群多实例并行消费；按通道（iOS/Android/短信）分队列，限速保护第三方通道配额。</li><li><strong>防重与幂等</strong>：任务 ID + 用户 ID 作为幂等键（Redis SETNX 或 DB 唯一索引），任务重跑不重复推送。</li><li><strong>失败重试</strong>：发送失败进重试队列，指数退避重试 3 次，仍失败进死信队列人工介入；短信通道失败可自动切换备用通道。</li><li><strong>防骚扰与合规</strong>：全局频控（单用户单日推送上限）、免打扰时段过滤、退订名单过滤。</li><li><strong>状态闭环</strong>：记录送达/点击回执，实时统计触达率，异常骤降触发告警熔断。</li></ul><p><strong>量化</strong>：千万用户 / 5 分钟送达 ≈ 3.3 万条/秒，需多通道并行 + 批量接口（如每批 100 条）；发送集群按通道配额反推实例数。</p><h4 id="🏭-实战场景-12" tabindex="-1"><a class="header-anchor" href="#🏭-实战场景-12"><span>🏭 实战场景</span></a></h4><details class="hint-container details"><summary>详情</summary><p><strong>千万级营销推送实战</strong></p><p>场景：晚 8 点大促开抢前给 1000 万目标用户发 Push。</p><p>圈选：圈选服务按标签位图产出人群，切 1000 片投 MQ。</p><p>发送：发送集群 20 实例、按 APNs/厂商通道分队列，单通道按其 QPS 配额限速。</p><p>节奏：如每通道 5000 QPS，4 通道即 2 万/秒，约 8 分钟触达千万级，需提前拉长窗口或多通道扩容。</p><p>过滤：发送前统一过频控/免打扰/退订三层过滤，实际发送量通常降 10%-30%。</p><p>监控：上线后以&quot;回执触达率&quot;为北极星指标，某通道骤降即自动切备用通道并告警。</p></details><h4 id="⚠️-常见误区-14" tabindex="-1"><a class="header-anchor" href="#⚠️-常见误区-14"><span>⚠️ 常见误区</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li>❌ &quot;发 MQ 就天然不重不漏&quot; → MQ 默认至少一次，去重必须靠业务幂等键（任务 ID + 用户 ID），不重靠发送前校验、不漏靠重试 + 死信。</li><li>❌ &quot;单队列单消费者慢慢发也能发完&quot; → 3.3 万条/秒的吞吐下，单消费者串行发送需几十分钟到小时级，必须分片 + 多实例并行。</li><li>❌ &quot;失败就无限重试&quot; → 无限重试会雪崩压垮通道，应指数退避有限重试 + 死信人工介入。</li></ul></details><h4 id="🔬-扩展知识-23" tabindex="-1"><a class="header-anchor" href="#🔬-扩展知识-23"><span>🔬 扩展知识</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li><p>【L3】亿级用户圈人为什么用位图？</p><p>圈人服务用位图（RoaringBitmap）交并差集运算，亿级用户多标签圈人可在秒级完成。</p><p>相比 SQL 多表 JOIN 快几个数量级。</p></li><li><p>【L3】推送队列的分片数与消费者数怎么配比？</p><p>分片数 ≥ 消费者实例数才能吃满并行度。</p><p>分片按 userId hash 还能保证同一用户的消息顺序。</p></li><li><p>【L4】多租户与不同优先级的推送怎么隔离？</p><p>营销（可延迟）与交易（验证码/订单）分队列隔离资源。</p><p>避免大促营销洪峰拖垮关键通知。</p></li></ul></details><h4 id="🔀-发散问题-16" tabindex="-1"><a class="header-anchor" href="#🔀-发散问题-16"><span>🔀 发散问题</span></a></h4><ul><li><p><strong>Q：会员过期提醒能复用这套系统吗？</strong></p><p>→ 能，它就是本系统的特例：圈选条件换成&quot;7 天后到期&quot;，见「500 万会员过期提醒」。</p></li><li><p><strong>Q：发送日志也是海量数据，后续要统计热词/热点怎么设计？</strong></p><p>→ 哈希分桶 + 堆取 Top，见「几亿条淘宝搜索日志」的同类方案。</p></li></ul><h3 id="【困难】如何设计数据同步方案-同步到数仓-⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【困难】如何设计数据同步方案-同步到数仓-⭐⭐⭐⭐"><span>【困难】如何设计数据同步方案（同步到数仓）？⭐⭐⭐⭐</span></a></h3><blockquote><p>🎯 目标等级：L3 ｜ ⏱ 建议用时：20 min ｜ 🏷 标签：功能设计 / 数据同步</p></blockquote><h4 id="💎-关键结论-24" tabindex="-1"><a class="header-anchor" href="#💎-关键结论-24"><span>💎 关键结论</span></a></h4><p>Canal 伪装从库解析 Binlog（业务零侵入），MQ 按业务 ID 分区保序，Flink 清洗写入数仓，断点续传 + 幂等去重 + 每日对账，做到不丢不重、顺序一致、延迟可控。</p><h4 id="⚡-记忆卡片-24" tabindex="-1"><a class="header-anchor" href="#⚡-记忆卡片-24"><span>⚡ 记忆卡片</span></a></h4><ul><li><strong>口诀</strong>：Canal 采 Binlog，分区保序，Flink 清洗，对账兜底。</li><li><strong>关键词</strong>：Binlog ／ 分区保序 ／ 断点续传</li><li><strong>链路</strong>：MySQL Binlog → Canal → MQ → Flink → 数仓</li></ul><h4 id="📖-核心知识-24" tabindex="-1"><a class="header-anchor" href="#📖-核心知识-24"><span>📖 核心知识</span></a></h4><p><strong>数据同步 = Canal 采集 Binlog + MQ 保序 + Flink 清洗 + 每日对账，核心是数据不丢不重、顺序一致、延迟可控。</strong></p><p><strong>总体架构</strong></p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>订单库（MySQL） → 变更捕获 → 消息队列 → 数据清洗 → 数仓（Hive/ClickHouse）</span></span>
<span class="line"><span>        ↑                          ↑</span></span>
<span class="line"><span>   业务无侵入                  可重试、保序</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>核心方案选型</strong></p><table><thead><tr><th style="text-align:left;">方案</th><th style="text-align:left;">原理</th><th style="text-align:left;">准确率</th><th style="text-align:left;">性能</th><th style="text-align:left;">复杂度</th><th style="text-align:left;">推荐</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Canal（Binlog）</strong></td><td style="text-align:left;">模拟 MySQL 从库解析 binlog</td><td style="text-align:left;"><strong>最高</strong></td><td style="text-align:left;"><strong>高</strong></td><td style="text-align:left;">中</td><td style="text-align:left;">⭐️ <strong>首选</strong></td></tr><tr><td style="text-align:left;"><strong>MQ 双写</strong></td><td style="text-align:left;">业务代码同步发 MQ</td><td style="text-align:left;">中</td><td style="text-align:left;">低</td><td style="text-align:left;">低</td><td style="text-align:left;">不推荐</td></tr><tr><td style="text-align:left;"><strong>DataX 离线抽取</strong></td><td style="text-align:left;">定时全量/增量抽取</td><td style="text-align:left;">高</td><td style="text-align:left;">低（T+1）</td><td style="text-align:left;">低</td><td style="text-align:left;">离线场景</td></tr><tr><td style="text-align:left;"><strong>Flink CDC</strong></td><td style="text-align:left;">实时流计算</td><td style="text-align:left;">高</td><td style="text-align:left;">高</td><td style="text-align:left;">高</td><td style="text-align:left;">实时数仓</td></tr></tbody></table><p><strong>方案权衡</strong>：Binlog 方案对业务零侵入但强依赖源库 binlog 格式（ROW 模式）与主从拓扑，分库分表后每库都要部署采集实例；业务双写 MQ 方案延迟低但侵入业务代码，且事务内发 MQ 有一致性问题。</p><p><strong>关键机制</strong></p><ul><li><strong>数据一致性保障</strong><ul><li>断点续传：记录 binlog 位点（position）</li><li>去重：MQ 消息幂等消费（订单 ID+版本号）</li><li>补偿：每日 T+1 对账，不一致重新同步</li><li>事务边界：binlog 事务原子性（同一事务一起发送）</li></ul></li><li><strong>顺序性保障</strong>：同一个订单的变更必须顺序处理 <ul><li>方案 1：MQ 分区键 = order_id（同订单进同一分区）</li><li>方案 2：Flink keyBy(order_id) 单线程处理</li></ul></li><li><strong>性能优化</strong><ul><li>批量发送：Canal 每 500ms/1000 条发送一次</li><li>压缩传输：启用 MQ 消息压缩（Gzip/Snappy）</li><li>目标优化：ClickHouse 批量写入（每批 1 万条）</li><li>分流处理：订单主表+明细表分开同步</li></ul></li></ul><p><strong>binlog 同步流程</strong></p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>订单库 → Canal → Kafka/RocketMQ → Flink/Spark → 数仓</span></span>
<span class="line"><span>  ↑         ↑          ↑              ↑</span></span>
<span class="line"><span>业务写   伪装从库   持久化消息      清洗、维表关联</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Canal 配置要点</strong></p><div class="language-properties line-numbers-mode" data-highlighter="shiki" data-ext="properties" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-properties"><span class="line"><span style="--shiki-light:#E45649;--shiki-dark:#C678DD;">canal.instance.master.address</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">=</span><span style="--shiki-light:#383A42;--shiki-dark:#98C379;">127.0.0.1:3306</span></span>
<span class="line"><span style="--shiki-light:#E45649;--shiki-dark:#C678DD;">canal.instance.dbUsername</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">=</span><span style="--shiki-light:#383A42;--shiki-dark:#98C379;">canal</span></span>
<span class="line"><span style="--shiki-light:#E45649;--shiki-dark:#C678DD;">canal.instance.dbPassword</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">=</span><span style="--shiki-light:#383A42;--shiki-dark:#98C379;">canal</span></span>
<span class="line"><span style="--shiki-light:#E45649;--shiki-dark:#C678DD;">canal.instance.filter.regex</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">=</span><span style="--shiki-light:#383A42;--shiki-dark:#98C379;">order_db.order_table  </span><span style="--shiki-light:#A0A1A7;--shiki-light-font-style:italic;--shiki-dark:#7F848E;--shiki-dark-font-style:italic;"># 监听表</span></span>
<span class="line"><span style="--shiki-light:#E45649;--shiki-dark:#C678DD;">canal.mq.topic</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">=</span><span style="--shiki-light:#383A42;--shiki-dark:#98C379;">order-binlog</span></span>
<span class="line"><span style="--shiki-light:#E45649;--shiki-dark:#C678DD;">canal.mq.partitionsHash</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">=</span><span style="--shiki-light:#383A42;--shiki-dark:#98C379;">order_id  </span><span style="--shiki-light:#A0A1A7;--shiki-light-font-style:italic;--shiki-dark:#7F848E;--shiki-dark-font-style:italic;"># 保序</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>数据质量保障</strong></p><p>实时监控：</p><ul><li>延迟监控：当前时间 - 最后一条同步时间 &lt; 5 分钟</li><li>数量监控：源库增量 ≈ 数仓增量（允许误差）</li><li>异常监控：解析失败率 &lt; 0.1%</li></ul><p>对账机制：每日凌晨执行，不一致则触发离线重新同步：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">SELECT</span><span style="--shiki-light:#0184BC;--shiki-dark:#56B6C2;"> COUNT</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">(*) </span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">FROM</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> order_db</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">.</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;">order_table</span></span>
<span class="line"><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">MINUS</span></span>
<span class="line"><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">SELECT</span><span style="--shiki-light:#0184BC;--shiki-dark:#56B6C2;"> COUNT</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">(*) </span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">FROM</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> dwd_order_table </span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">WHERE</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> dt </span><span style="--shiki-light:#383A42;--shiki-dark:#56B6C2;">=</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> 昨日</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>脏数据处理：</p><ol><li>格式错误 → 发到死信队列（人工介入）</li><li>维表不存在 → 先存待补表，维表到位后更新</li></ol><p><strong>容灾</strong></p><ul><li>主链路：Canal → Kafka（主集群）</li><li>备链路：DataX 每日全量（兜底）</li><li>Kafka 故障：消息积压，Canal 本地文件缓存（需配置）</li><li>数仓故障：消息持久化，恢复后重放</li></ul><p><strong>量化参考</strong>：日增 1000 万变更的库，binlog 增量约几 GB，Canal 解析 + MQ 传输延迟正常在秒级；Flink keyBy 单键串行处理，热点 key（大卖家）可能成为瓶颈，需盐值打散或拆分处理。</p><h4 id="🔬-扩展知识-24" tabindex="-1"><a class="header-anchor" href="#🔬-扩展知识-24"><span>🔬 扩展知识</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li><p>【L3】分库分表后怎么采集 binlog？</p><p>每分片库部署 Canal 实例（或一个 Canal 集群监听多实例），消息带上分片标识。</p><p>分区键仍用业务 ID（order_id）保证同订单变更进同一 Kafka 分区保序。</p><p>全量初始化用 DataX 并行抽取各分片。</p></li><li><p>【L3】源库 DDL 变更（加字段）时同步链路怎么处理？</p><p>数仓侧先加字段（向后兼容）再上线源库 DDL；Canal 解析到新结构自动适配。</p><p>新旧消息混合期内消费端需容忍字段缺失。</p><p>严禁先改源库后改数仓，会丢数据。</p></li><li><p>【L4】同步正确性怎么分层验证？</p><table><thead><tr><th>验证层</th><th>做法</th></tr></thead><tbody><tr><td>实时延迟监控</td><td>位点 lag</td></tr><tr><td>抽样比对</td><td>每小时随机抽 1000 条源库记录比对数仓</td></tr><tr><td>日终全量对账</td><td>COUNT + 关键字段 checksum</td></tr></tbody></table><p>发现差异自动触发位点回溯重放。</p></li><li><p>【L4】数据同步技术有什么演进方向？</p><p>Flink CDC 可一体化完成快照 + 增量与 Schema Evolution，减少 Canal + MQ 环节。</p><p>新建实时数仓可优先考虑。</p></li></ul><blockquote><p>📚 延伸阅读：<a href="https://github.com/alibaba/canal" target="_blank" rel="noopener noreferrer">Canal（alibaba）</a> ／ <a href="https://nightlies.apache.org/flink/flink-cdc-docs-stable/" target="_blank" rel="noopener noreferrer">Flink CDC 文档</a></p></blockquote></details><h4 id="🏭-实战场景-13" tabindex="-1"><a class="header-anchor" href="#🏭-实战场景-13"><span>🏭 实战场景</span></a></h4><details class="hint-container details"><summary>详情</summary><p><strong>订单库分库分表同步到数仓</strong></p><p>场景：订单库分 16 库 64 表，日增 2000 万订单、变更 1 亿次，要求同步到数仓延迟 &lt; 1 分钟、同订单变更保序。</p><p>采集：每分片库部署 Canal 实例（16 个）解析 ROW 格式 binlog，批量发送（500ms/1000 条）。</p><p>传输：Kafka 分区键 = order_id hash，保证同订单变更进同一分区保序。</p><p>分区数按吞吐估算（1 亿变更/日 ≈ 峰值数千 TPS，64 分区足够）。</p><p>加工：Flink keyBy(order_id) 清洗 + 维表关联后写 ClickHouse（批量 1 万条/批，避免频繁小写）。</p><p>监控：位点 lag 分钟级告警，日终对账 COUNT + checksum，差异自动回溯重放。</p><p><strong>积压事故教训</strong>：曾有线上事故：Canal 消费积压 6 小时未告警，数仓报表与在线库差异巨大误导运营决策——<strong>同步延迟必须有分钟级告警，不能只靠日终对账发现</strong>。</p></details><h4 id="⚠️-常见误区-15" tabindex="-1"><a class="header-anchor" href="#⚠️-常见误区-15"><span>⚠️ 常见误区</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li>❌ &quot;业务双写 MQ 比 Binlog 更可控&quot; → 双写侵入业务代码，事务内发 MQ 有一致性问题，且漏发无感知；Binlog 零侵入、天然按事务有序，是首选。</li><li>❌ &quot;有日终对账就够了&quot; → 积压、位点回退等问题当天无法发现，6 小时积压事故就是教训，必须配分钟级延迟告警。</li><li>❌ &quot;保序就要全局单分区&quot; → 牺牲全部吞吐；只需同一主键有序，按业务 ID（order_id）分区即可并行又保序。</li></ul></details><h4 id="🔀-发散问题-17" tabindex="-1"><a class="header-anchor" href="#🔀-发散问题-17"><span>🔀 发散问题</span></a></h4><ul><li><p><strong>Q：同步链路上线前的存量数据怎么办？</strong></p><p>→ DataX 并行全量抽取 + 记录位点后接增量，整体切换思路见「如何实现数据的不停服迁移？」。</p></li><li><p><strong>Q：同步延迟突增如何排查？</strong></p><p>→ 按链路分段定位（采集位点、MQ 积压、消费 TPS），监控埋点思路参考《场景与算法设计面试》『如何实现接口每分钟调用统计功能？』。</p></li></ul><h3 id="【困难】c4-模型与-adr-架构决策记录-在架构沟通中如何使用-⭐⭐⭐⭐" tabindex="-1"><a class="header-anchor" href="#【困难】c4-模型与-adr-架构决策记录-在架构沟通中如何使用-⭐⭐⭐⭐"><span>【困难】C4 模型与 ADR（架构决策记录）在架构沟通中如何使用？⭐⭐⭐⭐</span></a></h3><blockquote><p>🎯 目标等级：L3 ｜ ⏱ 建议用时：15 min ｜ 🏷 标签：架构方法论 / 架构沟通</p></blockquote><h4 id="💎-关键结论-25" tabindex="-1"><a class="header-anchor" href="#💎-关键结论-25"><span>💎 关键结论</span></a></h4><p>C4 模型用四层抽象（Context → Container → Component → Code）解决「对不同干系人说不同粒度的架构」；ADR（Architecture Decision Record）用轻量文档记录每个关键决策的背景、选项、结论与后果，让架构演进可追溯。两者互补：C4 回答「架构长什么样」，ADR 回答「为什么这样设计」。</p><h4 id="⚡-记忆卡片-25" tabindex="-1"><a class="header-anchor" href="#⚡-记忆卡片-25"><span>⚡ 记忆卡片</span></a></h4><ul><li><strong>口诀</strong>：C4 四层画架构，ADR 三选一留痕</li><li><strong>关键词</strong>：Context ／ Container ／ Component ／ Code ／ Status ／ Alternatives ／ Consequences</li><li><strong>链路</strong>：干系人分层 → C4 四层逐级下钻 → 决策点识别 → ADR 记录选项与权衡 → 可追溯架构演进</li></ul><h4 id="📖-核心知识-25" tabindex="-1"><a class="header-anchor" href="#📖-核心知识-25"><span>📖 核心知识</span></a></h4><p><strong>C4 模型——四层架构图</strong></p><p>Simon Brown 提出，解决「一张架构图无法同时面向高管和开发者」的问题：</p><table><thead><tr><th>层级</th><th>视角</th><th>受众</th><th>内容</th></tr></thead><tbody><tr><td>Level 1 Context</td><td>系统上下文</td><td>高管、产品、外部干系人</td><td>系统作为黑盒，与外部用户/系统的交互</td></tr><tr><td>Level 2 Container</td><td>容器</td><td>架构师、Tech Lead</td><td>可独立部署的运行单元（服务、DB、消息队列），技术选型</td></tr><tr><td>Level 3 Component</td><td>组件</td><td>开发者</td><td>容器内的模块划分，职责与接口</td></tr><tr><td>Level 4 Code</td><td>代码</td><td>开发者</td><td>类图/接口设计，仅在复杂模块时展开</td></tr></tbody></table><p>关键原则：</p><ul><li><strong>每层独立成图</strong>，不混层——一张图只讲一层故事；</li><li><strong>标注边界与职责</strong>，不画 UML 全家桶——重点是「谁做什么」而非「怎么实现」；</li><li><strong>配合 Structurizr 等工具</strong>，用代码（DSL）生成图，保持图与代码同步。</li></ul><p><strong>ADR——架构决策记录</strong></p><p>每个关键架构决策写一份 1~2 页的文档，核心字段：</p><table><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>Title</td><td>简短决策标题（如「ADR-023：选用 Kafka 作为事件总线」）</td></tr><tr><td>Status</td><td>Proposed / Accepted / Deprecated / Superseded</td></tr><tr><td>Context</td><td>问题背景与约束（为什么需要决策）</td></tr><tr><td>Decision</td><td>选了什么方案</td></tr><tr><td>Alternatives</td><td>考虑过哪些备选方案，各自的优劣</td></tr><tr><td>Consequences</td><td>决策带来的正/负面后果</td></tr></tbody></table><p>ADR 的价值：</p><ul><li><strong>防止「考古式」追问</strong>：新人入职或半年后回顾时，不用翻聊天记录猜「为什么选了 A 不选 B」；</li><li><strong>暴露隐含约束</strong>：写 Alternatives 时强制对比，避免锚定效应；</li><li><strong>可演进</strong>：旧决策被新决策 Supersede 时，保留历史链，形成决策演化脉络。</li></ul><details class="hint-container details"><summary>ADR 实际样例</summary><p><strong>ADR-015：订单创建采用异步事件驱动</strong></p><ul><li><strong>Status</strong>：Accepted（2025-06）</li><li><strong>Context</strong>：订单创建需同步扣库存、发积分、通知物流，链路长、RT 高、任一环节失败需回滚。</li><li><strong>Decision</strong>：订单创建只写 DB + 发领域事件，下游通过消费事件异步处理。</li><li><strong>Alternatives</strong>：① 同步 RPC 全链路——RT 2s+，任一失败全回滚；② MQ 广播——缺少事件溯源能力。</li><li><strong>Consequences</strong>：✅ RT 从 2s 降到 200ms；⚠️ 引入最终一致性，需补偿机制；⚠️ 事件顺序需保证。</li></ul></details><h4 id="🔬-扩展知识-25" tabindex="-1"><a class="header-anchor" href="#🔬-扩展知识-25"><span>🔬 扩展知识</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li><p>【L3】C4 与 UML 是什么关系？</p><p>C4 不是替代 UML，而是「选择性地用」——Level 4 可以用类图，Level 2 可以用部署图，但不强制。</p><p>核心是分层清晰，不是符号标准。</p></li><li><p>【L3】ADR 存在哪里、怎么检索？</p><p>通常放在代码仓库的 <code>docs/adr/</code> 目录下，用 MADR（Markdown ADR）模板。</p><p>配合 ADR CLI 工具（如 <code>adr-tools</code>）自动生成编号与索引。</p></li><li><p>【L4】C4 在微服务架构中怎么落地？</p><table><thead><tr><th>C4 层级</th><th>微服务中的对应</th></tr></thead><tbody><tr><td>Level 2 Container</td><td>API Gateway / 各服务 / DB / MQ 拓扑</td></tr><tr><td>Level 3 Component</td><td>服务内的分层（Controller → Service → Repository）</td></tr></tbody></table><p>但 Component 层在快速迭代中容易过时，建议只对核心域（如支付、订单）维护。</p></li><li><p>【L4】ADR 与敏捷开发怎么平衡？</p><p>不是每个 Sprint 都需要写 ADR——只在「影响面广、不可逆、有多种可选方案」的决策点写。</p><p>经验法则：如果一个决策错了需要 &gt; 2 周返工，就值得写 ADR。</p></li></ul></details><h4 id="🏭-实战场景-14" tabindex="-1"><a class="header-anchor" href="#🏭-实战场景-14"><span>🏭 实战场景</span></a></h4><details class="hint-container details"><summary>详情</summary><p><strong>某电商平台架构评审场景</strong></p><p>背景：CTO 要求每季度做一次架构评审，但团队 30+ 人，架构文档散落在 Confluence、飞书、代码注释中。</p><p>落地方案：</p><ol><li><strong>C4 建模</strong>：用 Structurizr DSL 维护 4 层图，CI 自动生成 PNG，嵌入 README；</li><li><strong>ADR 入库</strong>：在 monorepo 的 <code>docs/adr/</code> 下维护，每个 PR 涉及架构变更时必须附带 ADR；</li><li><strong>效果</strong>：新人 onboarding 时间从 3 周降到 1 周（C4 图快速理解系统全貌），架构追问减少 70%（ADR 自解释）。</li></ol></details><h4 id="⚠️-常见误区-16" tabindex="-1"><a class="header-anchor" href="#⚠️-常见误区-16"><span>⚠️ 常见误区</span></a></h4><details class="hint-container details"><summary>详情</summary><ul><li>❌ &quot;C4 要画四张图才算完整&quot; → 不是所有系统都需要 Level 4，大多数微服务维护到 Level 2~3 即可；Level 4 只在算法复杂或框架设计模块才展开。</li><li>❌ &quot;ADR 就是写文档，太慢&quot; → ADR 不是详细设计文档，1~2 页足够；核心价值在于「记录为什么」，不在于篇幅。</li><li>❌ &quot;架构图用 PPT 画就行&quot; → PPT 无法版本控制、无法 diff、无法 CI 生成；推荐 Structurizr / PlantUML / Mermaid 等代码化方案。</li></ul></details><h4 id="🔀-发散问题-18" tabindex="-1"><a class="header-anchor" href="#🔀-发散问题-18"><span>🔀 发散问题</span></a></h4><ul><li><p><strong>Q：C4 模型与 UML 组件图有什么区别？</strong></p><p>→ C4 是分层架构视角（四层逐级下钻），UML 组件图是单层内部关系；C4 更面向沟通，UML 更面向工程细节。</p></li><li><p><strong>Q：ADR 和 RFC（Request for Comments）有什么区别？</strong></p><p>→ RFC 侧重决策前的征求意见过程，ADR 侧重决策后的记录与追溯；实践中常先用 RFC 讨论，决策确定后写 ADR 归档。</p></li></ul>`,558)])])}const d=s(e,[["render",l]]),h=JSON.parse('{"path":"/pages/7266b738/","title":"业务系统设计面试","lang":"zh-CN","frontmatter":{"title":"业务系统设计面试","date":"2026-09-17T12:00:00.000Z","categories":["设计","面试"],"tags":["设计","面试","业务系统","系统设计"],"permalink":"/pages/7266b738/","description":"业务系统设计面试 业务系统 【困难】如何设计一个秒杀系统？⭐⭐⭐⭐⭐ 🎯 目标等级：L3-L4 ｜ ⏱ 建议用时：20 min ｜ 🏷 标签：系统设计 / 秒杀 💎 关键结论 秒杀应对的是瞬时海量请求，思路是「稳、准、快」：前端静态页 + CDN 挡读流量，答题 + 限流削峰，扣库存用 Redis + Lua 原子操作保证不超卖，只有扣减成功的请...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"业务系统设计面试\\",\\"image\\":[\\"https://raw.githubusercontent.com/dunwu/images/master/archive/2020/07/29c58abfb6e7455fa3711f014fcfb352.png\\",\\"https://raw.githubusercontent.com/dunwu/images/master/archive/2020/07/a2edeebfcfca47c0a91d64430927dd65.png\\"],\\"datePublished\\":\\"2026-09-17T12:00:00.000Z\\",\\"dateModified\\":\\"2026-10-05T15:23:45.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"钝悟\\",\\"url\\":\\"https://dunwu.github.io/waterdrop\\"}]}"],["meta",{"property":"og:url","content":"https://dunwu.github.io/waterdrop/waterdrop/pages/7266b738/"}],["meta",{"property":"og:site_name","content":"钝悟"}],["meta",{"property":"og:title","content":"业务系统设计面试"}],["meta",{"property":"og:description","content":"业务系统设计面试 业务系统 【困难】如何设计一个秒杀系统？⭐⭐⭐⭐⭐ 🎯 目标等级：L3-L4 ｜ ⏱ 建议用时：20 min ｜ 🏷 标签：系统设计 / 秒杀 💎 关键结论 秒杀应对的是瞬时海量请求，思路是「稳、准、快」：前端静态页 + CDN 挡读流量，答题 + 限流削峰，扣库存用 Redis + Lua 原子操作保证不超卖，只有扣减成功的请..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://raw.githubusercontent.com/dunwu/images/master/archive/2020/07/29c58abfb6e7455fa3711f014fcfb352.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-10-05T15:23:45.000Z"}],["meta",{"property":"article:tag","content":"系统设计"}],["meta",{"property":"article:tag","content":"业务系统"}],["meta",{"property":"article:tag","content":"面试"}],["meta",{"property":"article:tag","content":"设计"}],["meta",{"property":"article:published_time","content":"2026-09-17T12:00:00.000Z"}],["meta",{"property":"article:modified_time","content":"2026-10-05T15:23:45.000Z"}]]},"git":{"createdTime":1786264239000,"updatedTime":1791213825000,"contributors":[{"name":"dunwu","username":"dunwu","email":"forbreak@163.com","commits":6,"url":"https://github.com/dunwu"}]},"readingTime":{"minutes":113.11,"words":33934},"filePathRelative":"03.设计/面试/[设计][面试]业务系统设计.md","excerpt":"\\n<h2>业务系统</h2>\\n<h3>【困难】如何设计一个秒杀系统？⭐⭐⭐⭐⭐</h3>\\n<blockquote>\\n<p>🎯 目标等级：L3-L4 ｜ ⏱ 建议用时：20 min ｜ 🏷 标签：系统设计 / 秒杀</p>\\n</blockquote>\\n<h4>💎 关键结论</h4>\\n<p>秒杀应对的是瞬时海量请求，思路是「稳、准、快」：前端静态页 + CDN 挡读流量，答题 + 限流削峰，扣库存用 Redis + Lua 原子操作保证不超卖，只有扣减成功的请求进 MQ 异步建单。最终 DB 写入量等于库存量，而不是请求量。</p>\\n<h4>⚡ 记忆卡片</h4>\\n<ul>\\n<li><strong>口诀</strong>：静态挡、答题缓、限流削、Lua 扣</li>\\n<li><strong>关键词</strong>：瞬时海量请求 ／ 超卖 ／ 分层过滤 ／ Redis+Lua ／ 异步建单</li>\\n<li><strong>链路</strong>：前端静态 + CDN → 答题限流 → Redis Lua 扣库存 → MQ 削峰 → 异步建单 → 对账兜底</li>\\n</ul>","autoDesc":true}');export{d as comp,h as data};
